-- 3. Flagship Courses (4)
insert into public.courses (skill_id, slug, title, description, target_audience, outcomes, difficulty, estimated_duration_weeks, recommended_weekly_hours, recommended_schedule, prerequisites, thumbnail_url, author_name, completion_rules, publication_status, version, position)
select
  sk.id, v.slug, v.title, v.description, v.target_audience, v.outcomes, v.difficulty, v.estimated_duration_weeks, v.recommended_weekly_hours, v.recommended_schedule, v.prerequisites, v.thumbnail_url, v.author_name, v.completion_rules, v.publication_status, v.version, v.position
from (
  values
    ('frontend-development', 'frontend-development-foundations', 'Frontend Development Foundations', 'Master semantic HTML5, modern CSS layout systems, responsive design, modular JavaScript, DOM manipulation, form validation, and live static deployment.', 'Aspiring web developers, designers, and makers building responsive websites from scratch.', '["Write clean, accessible HTML5 documents with proper landmark and heading hierarchy","Build responsive multi-column interfaces using Flexbox, CSS Grid, and design tokens","Implement interactive DOM filtering, toggles, and validated forms in vanilla JavaScript","Audit and deploy a production-ready responsive business website to a live HTTPS URL"]'::jsonb, 'Beginner', 8, 5, '1 module (2 lessons + 1 practical exercise) per week', '["Basic comfort using a web browser and text editor"]'::jsonb, '', 'Kord Engineering Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'published', 1, 1),
    ('graphic-design', 'graphic-design-foundations', 'Graphic Design Foundations', 'Develop practical mastery in visual elements, colour theory, typography, grid composition, branding systems, digital tools, and print-ready production.', 'Beginners, content creators, and marketers creating crisp print and digital visuals.', '["Apply positive/negative space, scale contrast, and focal hierarchy deliberately","Build accessible 60-30-10 colour systems across RGB and CMYK workflows","Pair complementary typefaces with disciplined leading, tracking, and grid alignment","Produce and export a print-ready promotional flyer grounded in a coherent brand sheet"]'::jsonb, 'Beginner', 8, 4.5, '1 module (2 lessons + 1 studio exercise) per week', '["Access to any free or desktop design editor (Figma, Canva, Inkscape, or Affinity)"]'::jsonb, '', 'Kord Visual Design Studio', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'published', 1, 1),
    ('digital-marketing-fundamentals', 'digital-marketing-foundations', 'Digital Marketing Foundations', 'Learn full-funnel digital marketing from audience research, content pillars, social strategy, and conversion copywriting to campaign planning, analytics, and optimisation.', 'Beginners, founders, freelancers, and junior marketers planning structured growth campaigns.', '["Map customer journeys across Owned, Earned, and Paid channels cleanly","Conduct voice-of-customer audience research and write PAS/AIDA conversion copy","Plan a 7-day multi-channel campaign complete with standardised UTM attribution","Interpret CTR, CVR, CPA, and ROAS metrics to design disciplined A/B tests"]'::jsonb, 'Beginner', 8, 4.5, '1 module (2 lessons + 1 applied worksheet) per week', '["No prior marketing background required"]'::jsonb, '', 'Kord Growth & Marketing Faculty', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'published', 1, 1),
    ('public-speaking', 'communication-and-public-speaking', 'Communication and Public Speaking', 'Build clear everyday workplace communication and poised public speaking skills—covering active listening, vocal pacing, body language, persuasion, structure, delivery, and self-review.', 'Professionals, students, team leads, and founders preparing talks, pitches, and confident briefings.', '["Structure spoken talks and updates around audience priorities and the Rule of Three","Control vocal pacing, intentional anchor pauses, and grounded non-verbal presence","Weave Ethos, Pathos, and Logos ethically while handling Q&A calmly","Deliver, record, and critique a structured 2-minute presentation with reflection"]'::jsonb, 'Beginner', 8, 4, '1 module (2 lessons + 1 speaking drill) per week', '["No prior public speaking experience required"]'::jsonb, '', 'Kord Communication Lab', '{"requireAllRequiredLessons":true,"requireAllActivities":true,"requireAllAssessments":true,"requireChallengeSubmission":true,"requireChallengeApproval":true}'::jsonb, 'published', 1, 1)
) as v(skill_slug, slug, title, description, target_audience, outcomes, difficulty, estimated_duration_weeks, recommended_weekly_hours, recommended_schedule, prerequisites, thumbnail_url, author_name, completion_rules, publication_status, version, position)
join public.skills sk on sk.slug = v.skill_slug
on conflict (slug) do update set
  skill_id = excluded.skill_id,
  title = excluded.title,
  description = excluded.description,
  target_audience = excluded.target_audience,
  outcomes = excluded.outcomes,
  difficulty = excluded.difficulty,
  estimated_duration_weeks = excluded.estimated_duration_weeks,
  recommended_weekly_hours = excluded.recommended_weekly_hours,
  recommended_schedule = excluded.recommended_schedule,
  prerequisites = excluded.prerequisites,
  thumbnail_url = excluded.thumbnail_url,
  author_name = excluded.author_name,
  completion_rules = excluded.completion_rules,
  publication_status = excluded.publication_status,
  version = excluded.version,
  position = excluded.position,
  updated_at = now();

-- 4. Course-Skill Associations (16)
insert into public.course_skills (course_id, skill_id, is_primary)
select co.id, sk.id, v.is_primary
from (
  values
    ('frontend-development-foundations', 'frontend-development', true),
    ('frontend-development-foundations', 'web-development', false),
    ('graphic-design-foundations', 'graphic-design', true),
    ('graphic-design-foundations', 'visual-communication', false),
    ('graphic-design-foundations', 'brand-identity-design', false),
    ('graphic-design-foundations', 'canva-design', false),
    ('digital-marketing-foundations', 'digital-marketing-fundamentals', true),
    ('digital-marketing-foundations', 'content-marketing', false),
    ('digital-marketing-foundations', 'social-media-management', false),
    ('digital-marketing-foundations', 'copywriting', false),
    ('digital-marketing-foundations', 'marketing-analytics', false),
    ('communication-and-public-speaking', 'public-speaking', true),
    ('communication-and-public-speaking', 'effective-communication', false),
    ('communication-and-public-speaking', 'presentation-skills', false),
    ('communication-and-public-speaking', 'persuasion-and-influence', false),
    ('communication-and-public-speaking', 'active-listening', false)
) as v(course_slug, skill_slug, is_primary)
join public.courses co on co.slug = v.course_slug
join public.skills sk on sk.slug = v.skill_slug
on conflict (course_id, skill_id) do update set is_primary = excluded.is_primary;

