-- 6. Phases / Modules (32)
insert into public.phases (id, course_id, skill_id, position, title, summary, objectives, difficulty, est_hours, publication_status)
select v.id::uuid, co.id, co.skill_id, v.position, v.title, v.summary, v.objectives, v.difficulty, v.est_hours, v.publication_status
from (
  values
    ('1452f148-671a-6af7-3d7d-91427b39afa1', 'frontend-development-foundations', 1, 'Introduction to Web Development', 'Understand how browsers, HTTP requests, HTML/CSS/JavaScript, and developer tools collaborate to render websites.', '["Explain the browser request-response cycle and separation of structure, presentation, and behaviour","Inspect live DOM trees and computed CSS styles using browser Developer Tools"]'::jsonb, 'Beginner', 2.5, 'published'),
    ('d038cf02-89ce-4d92-fa33-4a10e271793e', 'frontend-development-foundations', 2, 'HTML Fundamentals', 'Author semantic, accessible HTML5 documents with proper headings, landmarks, links, tables, and media attributes.', '["Structure full pages with semantic landmarks (<header>, <main>, <section>, <article>, <footer>)","Write descriptive alt text, ordered headings, and accessible interactive elements"]'::jsonb, 'Beginner', 3, 'published'),
    ('2d272456-d4a8-88d6-a92e-1eb58dcc0503', 'frontend-development-foundations', 3, 'CSS Fundamentals', 'Control selectors, specificity, cascade order, typography, CSS custom properties, and the CSS Box Model accurately.', '["Predict cascade and specificity winners without resorting to !important","Apply box-sizing: border-box, margin/padding rhythm, and design tokens via CSS variables"]'::jsonb, 'Beginner', 3.5, 'published'),
    ('1939f24b-98de-af0a-4beb-3217cfcdacba', 'frontend-development-foundations', 4, 'Layout and Responsive Design', 'Architect mobile-first Flexbox rows, CSS Grid multi-column layouts, fluid spacing, and responsive breakpoints.', '["Choose between Flexbox (1D alignment) and CSS Grid (2D layout tracks)","Build responsive multi-column grids using repeat(auto-fit, minmax(...)) and mobile-first media queries"]'::jsonb, 'Intermediate', 4, 'published'),
    ('420b4329-9c17-0c00-c0fd-c951a1cc859a', 'frontend-development-foundations', 5, 'JavaScript Fundamentals', 'Master variables, data types, functions, arrays, objects, conditionals, and immutable array transformations.', '["Write pure functions using const/let, arrow functions, and template literals","Transform arrays of objects cleanly with filter(), map(), find(), and reduce()"]'::jsonb, 'Intermediate', 4, 'published'),
    ('b5b3aedb-70a3-ad9b-f3cc-53d5e98b49e8', 'frontend-development-foundations', 6, 'DOM Manipulation', 'Select elements, attach event listeners, delegate dynamic click events, and update UI state safely without XSS.', '["Query DOM nodes and bind clean addEventListener handlers","Render dynamic lists safely using textContent or escaped templates instead of raw user HTML"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('fd887f97-0b99-8407-d9b7-28bc23d4f741', 'frontend-development-foundations', 7, 'Forms and Validation', 'Design accessible HTML forms with paired labels, native constraints, custom JS validation, and clear inline feedback.', '["Connect every <input>, <select>, and <textarea> to a visible <label for=\"...\">","Combine HTML5 constraints with friendly custom JavaScript error messages"]'::jsonb, 'Intermediate', 3, 'published'),
    ('d4e2b59d-c916-e976-6b79-4d636f308e48', 'frontend-development-foundations', 8, 'Website Integration and Deployment', 'Connect pages cleanly, optimise images and metadata, run pre-launch QA audits, and deploy a live static site.', '["Configure SEO title/meta tags, favicons, and clean relative internal links","Audit performance, responsiveness, and accessibility before deploying to static hosting"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('31078ffa-e680-0e73-5784-4bc0204f658f', 'graphic-design-foundations', 1, 'Introduction to Graphic Design', 'Understand graphic design as structured visual problem-solving across print, editorial, branding, and digital media.', '["Differentiate artistic expression from goal-driven visual communication","Deconstruct a creative brief into audience, message, and format constraints"]'::jsonb, 'Beginner', 2.5, 'published'),
    ('5cb69c74-cde2-63c7-9eff-99d475b442fe', 'graphic-design-foundations', 2, 'Elements of Design', 'Master line, shape, form, texture, space, and scale contrast to direct the viewer’s eye intentionally.', '["Use positive and negative space actively rather than crowding corners","Combine geometric and organic shapes with deliberate scale contrast"]'::jsonb, 'Beginner', 3, 'published'),
    ('72747bc7-f08d-7150-456f-63ed8621c540', 'graphic-design-foundations', 3, 'Colour Theory', 'Apply hue, saturation, value, colour harmonies, 60-30-10 ratios, and accessible contrast in RGB and CMYK.', '["Build disciplined 60-30-10 colour systems (canvas, structure, focal accent)","Distinguish RGB screen colour from CMYK ink colour and verify WCAG text legibility"]'::jsonb, 'Beginner', 3, 'published'),
    ('a536bd2d-4629-4ffd-e289-1fb96a3701db', 'graphic-design-foundations', 4, 'Typography', 'Select complementary typeface pairings, build clear modular type scales, and control tracking, leading, and alignment.', '["Pair at most two complementary font families (Display + Body)","Set readable line-height (leading), letter-spacing (tracking), and left-aligned rags"]'::jsonb, 'Beginner', 3.5, 'published'),
    ('649489f2-ad65-af24-188f-a3aa20b13aa2', 'graphic-design-foundations', 5, 'Layout and Composition', 'Construct Swiss grid columns, visual hierarchy paths, balanced alignments, and clean page proportions.', '["Use modular column grids and consistent margin gutters","Guide eye flow intentionally using Z-pattern or F-pattern focal anchors"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('01eaf2c3-097d-3b9f-0c1d-97df91122f34', 'graphic-design-foundations', 6, 'Branding Fundamentals', 'Connect brand positioning, tone, logo lockups, and mini style guides across customer touchpoints.', '["Articulate brand personality traits before sketching marks","Assemble a cohesive mini brand kit (logo safe space, palette, typography)"]'::jsonb, 'Intermediate', 3, 'published'),
    ('d1af902a-0525-a077-325b-48ae16152342', 'graphic-design-foundations', 7, 'Digital Design Tools', 'Work cleanly with vector shapes vs raster pixels, layers, reusable styles, and non-destructive editing workflows.', '["Choose vector graphics (SVG/PDF) for logos/type and high-res raster (PNG/JPG) for photos","Organise named layers, frames, and reusable colour/text styles"]'::jsonb, 'Intermediate', 3, 'published'),
    ('70274843-cdb0-65d3-eec9-1e9773769b27', 'graphic-design-foundations', 8, 'Professional Design Production', 'Prepare print-ready files (bleed, trim marks, safe zones), export crisp digital assets, and write client-ready design rationales.', '["Set 3mm bleed, trim safety margins, and outline/embed fonts properly","Export both print PDF and high-res digital PNG/WebP variants cleanly"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('6ee2ae2b-51e5-30da-6985-df81dcd26c65', 'digital-marketing-foundations', 1, 'Introduction to Digital Marketing', 'Connect customer acquisition, conversion funnels, owned/earned/paid channels, and clear commercial objectives.', '["Map Awareness, Consideration, Conversion, and Retention funnel stages","Distinguish Owned, Earned, and Paid digital media channels"]'::jsonb, 'Beginner', 2.5, 'published'),
    ('4fbbb134-2d0a-2a8f-0cd3-2e5d2da2f1ac', 'digital-marketing-foundations', 2, 'Audience Research', 'Move beyond vague demographics by documenting buyer pain points, triggers, objections, and search intent.', '["Conduct lightweight voice-of-customer research from reviews and interviews","Build an actionable Ideal Customer Profile (ICP) grounded in real quotes"]'::jsonb, 'Beginner', 3, 'published'),
    ('eef6d687-2e34-9aa3-e674-dc02fe223505', 'digital-marketing-foundations', 3, 'Content Marketing', 'Plan educational content pillars, repurpose flagship guides into micro-assets, and build organic trust.', '["Define 3–4 repeatable content pillars tied to buyer questions","Repurpose one deep piece into short articles, carousels, and emails"]'::jsonb, 'Beginner', 3, 'published'),
    ('8927aa09-f63d-ace2-96c4-a60f0deee13b', 'digital-marketing-foundations', 4, 'Social Media Marketing', 'Select the right social channels, structure balanced weekly cadences, spark genuine engagement, and format native posts.', '["Choose 1–2 primary platforms matched to audience habits instead of posting everywhere","Balance reach, trust-building, and conversion posts across a week"]'::jsonb, 'Beginner', 3, 'published'),
    ('5f2f372b-dd2c-ac45-c4dc-55da52b3fdc4', 'digital-marketing-foundations', 5, 'Copywriting', 'Write persuasive, clear headlines, PAS/AIDA frameworks, specific benefits, and friction-free calls-to-action.', '["Translate technical product features into concrete customer outcomes","Structure landing sections and emails using Problem–Agitate–Solve (PAS) and AIDA"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('114e11c2-a54b-c081-a03a-cb36e2526054', 'digital-marketing-foundations', 6, 'Campaign Planning', 'Coordinate multi-day launches combining editorial calendars, email sequences, paid touchpoints, and UTM tracking.', '["Design a cohesive 7-day launch calendar across complementary channels","Tag every campaign link cleanly with UTM parameters"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('9f52fbd6-9d99-0385-cee9-e5387e33ec33', 'digital-marketing-foundations', 7, 'Digital Marketing Analytics', 'Separate vanity metrics from actionable KPIs—CTR, Conversion Rate, CPA, CAC, ROAS, and cohort retention.', '["Calculate CTR, Conversion Rate, CPA, and ROAS accurately","Diagnose where a campaign funnel is leaking before changing ads blindly"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('9fb320ae-27f3-b05e-789b-a184bc9e631a', 'digital-marketing-foundations', 8, 'Campaign Optimisation', 'Run disciplined single-variable A/B tests, catch creative fatigue, and iterate campaigns systematically.', '["Formulate testable hypotheses (Change X -> Improve Y -> Because Z)","Avoid ending A/B tests prematurely on tiny sample sizes"]'::jsonb, 'Intermediate', 3, 'published'),
    ('a37791dc-3d3a-9c1a-2ea0-d13fe9246459', 'communication-and-public-speaking', 1, 'Communication Fundamentals', 'Master the sender-message-receiver loop, reduce signal noise, and establish mutual understanding before speaking at length.', '["Identify physical, semantic, and emotional communication noise","Frame clear messages around shared purpose and listener needs"]'::jsonb, 'Beginner', 2.5, 'published'),
    ('de26ab8c-a851-617c-5422-c354be6c14a7', 'communication-and-public-speaking', 2, 'Effective Verbal Communication', 'Sharpen vocal clarity, deliberate pacing, intentional pauses, plain language, and filler-word reduction.', '["Use 1-second silent pauses instead of \"um\" and \"like\" fillers","Vary pitch, volume, and pacing to highlight key takeaways"]'::jsonb, 'Beginner', 3, 'published'),
    ('ee983d8d-2805-6161-6ecf-c65338897282', 'communication-and-public-speaking', 3, 'Non-verbal Communication', 'Align posture, grounded stance, open hand gestures, eye contact, and camera framing with your spoken message.', '["Eliminate swaying and distracting nervous hand habits","Practise steady eye-contact zones in both live rooms and webcam calls"]'::jsonb, 'Beginner', 2.5, 'published'),
    ('667f0407-11a9-0e7c-1d61-dc368efd2f01', 'communication-and-public-speaking', 4, 'Audience Analysis', 'Tailor depth, vocabulary, examples, and emotional framing to executive, technical, community, or client audiences.', '["Map audience knowledge level, primary concerns, and decision authority","Adapt one core topic cleanly for two starkly different audiences"]'::jsonb, 'Beginner', 3, 'published'),
    ('0094ebe1-50a1-eb7f-a60d-a31d7cf80bbb', 'communication-and-public-speaking', 5, 'Presentation Structure', 'Architect talks using Rule of Three, strong opening hooks, logical signposts, and memorable conclusions.', '["Open without awkward throat-clearing (\"Um, hi everyone, so today...\")","Organise talks cleanly into Hook -> 3 Supporting Points -> Memorable Close"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('093c960b-d447-0ba6-c2ef-5cf102b861cb', 'communication-and-public-speaking', 6, 'Persuasive Communication', 'Balance Ethos, Pathos, and Logos ethically, handle tough objections calmly, and pair stories with hard evidence.', '["Combine credibility (Ethos), human stakes (Pathos), and logic/data (Logos)","Respond constructively to sceptical questions using Acknowledge–Bridge–Evidence"]'::jsonb, 'Intermediate', 3.5, 'published'),
    ('5b22e202-5186-acaa-dd56-23c790c35cf6', 'communication-and-public-speaking', 7, 'Presentation Delivery', 'Manage stage nerves physiologically, rehearse with timed cue cards rather than rote scripts, and recover smoothly.', '["Use box breathing and physical grounding prior to stepping on stage","Rehearse aloud against a strict 2-minute stopwatch using keyword cue cards"]'::jsonb, 'Intermediate', 3, 'published'),
    ('150dc5cb-6006-190d-a257-5f17784ef5bb', 'communication-and-public-speaking', 8, 'Feedback and Improvement', 'Conduct structured self-reviews across audio, visuals, and content, give constructive peer critiques, and iterate rapidly.', '["Audit a recorded talk separately for Audio-only, Video-muted, and Content flow","Turn raw critique into specific rehearsal adjustments"]'::jsonb, 'Intermediate', 3, 'published')
) as v(id, course_slug, position, title, summary, objectives, difficulty, est_hours, publication_status)
join public.courses co on co.slug = v.course_slug
on conflict (id) do update set
  course_id = excluded.course_id,
  skill_id = excluded.skill_id,
  position = excluded.position,
  title = excluded.title,
  summary = excluded.summary,
  objectives = excluded.objectives,
  difficulty = excluded.difficulty,
  est_hours = excluded.est_hours,
  publication_status = excluded.publication_status;

-- 7. Lessons (64)
insert into public.lessons (id, phase_id, position, title, introduction, objectives, est_minutes, blocks, videos, summary, takeaways, further_reading, completion_criteria, publication_status, is_required)
values
  ('b98f5e89-eb1d-d146-03f7-1c84cf0188fd'::uuid, '1452f148-671a-6af7-3d7d-91427b39afa1'::uuid, 1, 'How the Web Works: Browsers, HTTP, and Rendering', 'Every webpage starts as plain text sent over HTTP and transformed by the browser engine into pixels, layout boxes, and interactive scripts.', '["Trace an HTTP request from URL entry to painted pixels","Differentiate HTML structure, CSS presentation, and JavaScript behaviour"]'::jsonb, 25, '[{"id":"fe11-1","type":"heading","text":"From URL to Rendered Page"},{"id":"fe11-2","type":"paragraph","text":"When a visitor types a URL, the browser resolves the domain name via DNS, opens a secure HTTPS connection, and requests the HTML document. As the HTML streams in, the browser builds the Document Object Model (DOM), fetches linked stylesheets to build the CSS Object Model (CSSOM), combines them into a Render Tree, calculates box geometry (Layout), and paints pixels to the screen."},{"id":"fe11-3","type":"table","title":"The Three Core Frontend Layers","headers":["Layer","Responsibility","Best Practice"],"rows":[["HTML","Semantic meaning and document outline","Choose elements by meaning (<nav>, <article>), not appearance"],["CSS","Visual typography, colour, spacing, and layout","Keep styling decoupled from markup using classes and variables"],["JavaScript","Dynamic state, events, validation, and data fetching","Progressively enhance semantic markup rather than breaking native links"]]},{"id":"fe11-4","type":"knowledge_check","prompt":"Which two internal trees does the browser combine before computing element positions on screen?","options":["DNS Tree and File Tree","DOM and CSSOM","JSON Tree and Event Loop"],"correctIndex":1,"explanation":"The browser merges the parsed HTML (DOM) and parsed styles (CSSOM) into the Render Tree prior to Layout and Paint."}]'::jsonb, '[]'::jsonb, 'Clean web engineering keeps content semantics in HTML, visual design in CSS, and interactive state in JavaScript.', '["Browsers parse HTML into the DOM and CSS into the CSSOM","Render-blocking CSS delays first paint","Semantic separation makes sites accessible and easier to maintain"]'::jsonb, '[{"title":"MDN: How the Web Works","url":"https://developer.mozilla.org/en-US/docs/Learn/Getting_started_with_the_web/How_the_Web_works"},{"title":"web.dev: Critical Rendering Path","url":"https://web.dev/articles/critical-rendering-path"}]'::jsonb, 'Read the rendering cycle guide, answer the inline knowledge check, and mark this lesson complete.', 'published', true),
  ('6ace6ba6-1961-083e-1874-dc919fa0d7e7'::uuid, '1452f148-671a-6af7-3d7d-91427b39afa1'::uuid, 2, 'Project Folder Hygiene & Browser DevTools', 'Consistent project organisation and DevTools inspection save hours of guesswork when diagnosing broken paths or layout bugs.', '["Organise clean relative asset paths for HTML, CSS, JS, and images","Use DevTools Elements and Console panels to test edits live"]'::jsonb, 20, '[{"id":"fe12-1","type":"heading","text":"Clean Static Site Project Structure"},{"id":"fe12-2","type":"code","title":"Recommended Starter Directory Tree","language":"text","code":"business-site/\n├── index.html\n├── about.html\n├── contact.html\n├── styles/\n│   └── main.css\n├── scripts/\n│   └── app.js\n└── images/\n    └── hero.webp"},{"id":"fe12-3","type":"steps","title":"Debugging Styles in DevTools","items":["Right-click any page element and choose Inspect.","Check the Computed tab to trace which stylesheet rule won specificity.","Toggle device toolbar (Ctrl/Cmd + Shift + M) to test 375px mobile width."]}]'::jsonb, '[]'::jsonb, 'Treat lowercase filenames, relative paths, and DevTools inspection as daily engineering habits.', '["Avoid spaces and uppercase letters in file paths","Always inspect Computed styles when rules do not apply"]'::jsonb, '[{"title":"Chrome DevTools Overview","url":"https://developer.chrome.com/docs/devtools/overview"}]'::jsonb, 'Review the directory convention and DevTools steps, then mark complete.', 'published', true),
  ('1eb2c22a-a91d-9426-a8ec-3fce9a2bddc0'::uuid, 'd038cf02-89ce-4d92-fa33-4a10e271793e'::uuid, 1, 'Document Anatomy, Landmarks, and Semantic Tags', 'Screen readers and search engines rely on HTML landmarks and heading hierarchy—not visual font sizes—to navigate a page.', '["Use <header>, <nav>, <main>, <section>, <article>, and <footer> properly","Maintain logical heading nesting from <h1> through <h3>"]'::jsonb, 25, '[{"id":"fe21-1","type":"heading","text":"Why Semantics Beat Generic Div Soup"},{"id":"fe21-2","type":"paragraph","text":"Replacing meaningless <div> wrappers with semantic landmarks gives assistive technology users instant keyboard shortcuts to jump straight to main content or navigation. Similarly, using <button type=\"button\"> instead of a clickable <div> provides keyboard Enter/Space support and focusability automatically."},{"id":"fe21-3","type":"code","title":"Accessible Semantic Page Skeleton","language":"html","code":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Harbour Bakery — Fresh Sourdough Daily</title>\n</head>\n<body>\n  <header>\n    <nav aria-label=\"Primary\">\n      <a href=\"/\">Harbour Bakery</a>\n      <a href=\"#menu\">Menu</a>\n      <a href=\"#contact\">Contact</a>\n    </nav>\n  </header>\n  <main>\n    <section aria-labelledby=\"hero-title\">\n      <h1 id=\"hero-title\">Stone-Milled Bread Baked Every Morning</h1>\n    </section>\n  </main>\n  <footer>\n    <p>&copy; 2026 Harbour Bakery</p>\n  </footer>\n</body>\n</html>"},{"id":"fe21-4","type":"knowledge_check","prompt":"Which element should you use for an interactive action that opens a mobile menu without navigating to a URL?","options":["<div class=\"btn\">","<a href=\"#\">","<button type=\"button\">"],"correctIndex":2,"explanation":"<button type=\"button\"> natively supports keyboard focus, Enter/Space activation, and assistive screen-reader announcements."}]'::jsonb, '[]'::jsonb, 'Semantic landmarks create an accessible document backbone before a single line of CSS is written.', '["Include <meta name=\"viewport\"> on every page","Keep heading hierarchy sequential without jumping from h1 to h4"]'::jsonb, '[{"title":"MDN: HTML Elements Reference","url":"https://developer.mozilla.org/en-US/docs/Web/HTML/Element"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('ba4712d5-9ea0-d90b-3ef7-5fb2a00430e0'::uuid, 'd038cf02-89ce-4d92-fa33-4a10e271793e'::uuid, 2, 'Links, Images, Lists, and Accessible Tables', 'Media and structured data need clean attributes so pages remain usable on slow networks and screen readers.', '["Distinguish informative vs decorative image alt attributes","Build accessible data tables with <thead>, <tbody>, and scope attributes"]'::jsonb, 25, '[{"id":"fe22-1","type":"definition","term":"Informative vs Decorative Alt Text","meaning":"Informative images describe the information conveyed (alt=\"Three seeded rye loaves on a cooling rack\"). Purely decorative icons use an empty alt=\"\" so screen readers skip them cleanly."},{"id":"fe22-2","type":"callout","title":"Avoid \"Click Here\" Links","text":"Write descriptive link text such as \"Read our wholesale pricing guide\" instead of generic \"Click here\" so users scanning links out of context know the destination."}]'::jsonb, '[]'::jsonb, 'Descriptive link labels, clean alt attributes, and explicit table headers raise baseline accessibility immediately.', '["Always include width/height or aspect-ratio to prevent layout jump","Use <th scope=\"col\"> for column headers"]'::jsonb, '[{"title":"W3C WAI: Images Tutorial","url":"https://www.w3.org/WAI/tutorials/images/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('00756f8d-d14d-1a08-a775-43d0cfcb465d'::uuid, '2d272456-d4a8-88d6-a92e-1eb58dcc0503'::uuid, 1, 'Cascade, Specificity, and CSS Custom Properties', 'CSS bugs rarely happen at random—they happen when specificity conflicts or unorganised overrides fight each other.', '["Calculate selector specificity (ID vs Class vs Element)","Centralise brand colours and radii in :root custom properties"]'::jsonb, 25, '[{"id":"fe31-1","type":"paragraph","text":"Browser styles apply according to Origin, Specificity, and Source Order. Keep selectors flat—prefer single classes like .card-title over deeply nested chains like #main div ul li a so any modifier class can override cleanly."},{"id":"fe31-2","type":"code","title":"Clean :root Design Tokens","language":"css","code":":root {\n  --bg-page: #f8fafc;\n  --bg-surface: #ffffff;\n  --text-main: #0f172a;\n  --text-muted: #475569;\n  --brand-primary: #1d4ed8;\n  --radius-card: 12px;\n}\n\n.btn-primary {\n  background: var(--brand-primary);\n  color: #ffffff;\n  padding: 10px 18px;\n  border-radius: 8px;\n}"},{"id":"fe31-3","type":"knowledge_check","prompt":"Which selector has the highest specificity?","options":[".nav .nav-link","#header-cta","header nav a"],"correctIndex":1,"explanation":"An ID selector (#header-cta = 1-0-0) outweighs any number of class (0-2-0) or element (0-0-3) selectors."}]'::jsonb, '[]'::jsonb, 'Flat class architecture paired with CSS custom properties makes themes consistent and refactoring painless.', '["Reserve IDs for anchors and JS hooks, not CSS styling","Store palette and spacing scales in :root variables"]'::jsonb, '[{"title":"MDN: Specificity","url":"https://developer.mozilla.org/en-US/docs/Web/CSS/Specificity"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('0bf16bd7-ad6e-feed-c5a7-8c99b5d11f69'::uuid, '2d272456-d4a8-88d6-a92e-1eb58dcc0503'::uuid, 2, 'The CSS Box Model, Typography, and Colour Contrast', 'Every element in CSS occupies a rectangular box made of content, padding, border, and outer margin.', '["Apply box-sizing: border-box globally","Establish readable font-size, line-height (1.5–1.65), and AA contrast"]'::jsonb, 25, '[{"id":"fe32-1","type":"example","title":"Why border-box Prevents Horizontal Overflow","body":"With default content-box, width: 100% plus padding: 24px creates a box wider than 100%, triggering horizontal scrollbars. Setting *, *::before, *::after { box-sizing: border-box; } includes padding and border inside the declared width."},{"id":"fe32-2","type":"bullets","title":"Readable Typography Rules","items":["Set body prose between 15px and 17px with 1.6 line-height.","Limit line length to 60–75ch so the eye tracks easily.","Verify normal text achieves at least 4.5:1 colour contrast."]}]'::jsonb, '[]'::jsonb, 'Predictable box sizing and legible typographic rhythm instantly elevate interface clarity.', '["Always declare *, *::before, *::after { box-sizing: border-box; }","Use margin between siblings and padding inside containers"]'::jsonb, '[{"title":"MDN: The Box Model","url":"https://developer.mozilla.org/en-US/docs/Learn/CSS/Building_blocks/The_box_model"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('a513fd17-0366-744d-9f4b-f73a5e2832d9'::uuid, '1939f24b-98de-af0a-4beb-3217cfcdacba'::uuid, 1, 'Flexbox Alignment & Navigation Bars', 'Flexbox solves one-dimensional alignment—distributing navigation links, button rows, and card footers along a row or column.', '["Distinguish justify-content (main axis) from align-items (cross axis)","Use gap and flex-wrap to prevent squished controls on small screens"]'::jsonb, 25, '[{"id":"fe41-1","type":"code","title":"Clean Header Bar with Flexbox","language":"css","code":".site-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 24px;\n  flex-wrap: wrap;\n}"},{"id":"fe41-2","type":"callout","title":"Prefer gap Over Margin Hacks","text":"Using gap: 16px on a flex or grid container spaces child items evenly without needing :last-child margin resets."}]'::jsonb, '[]'::jsonb, 'Flexbox excels at toolbars, card headers, and horizontal or vertical alignment along one axis.', '["justify-content aligns along flex-direction","align-items aligns perpendicular to flex-direction","Add min-width: 0 to flex children that contain long text"]'::jsonb, '[{"title":"MDN: Basic Concepts of Flexbox","url":"https://developer.mozilla.org/en-US/docs/Web/CSS/CSS_flexible_box_layout/Basic_concepts_of_flexbox"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('400ddbf9-4364-3d71-8f32-d885f8eee3d3'::uuid, '1939f24b-98de-af0a-4beb-3217cfcdacba'::uuid, 2, 'CSS Grid, Fluid Sizing, and Mobile-First Breakpoints', 'CSS Grid controls rows and columns simultaneously, letting layouts adapt from single-column mobile views to structured desktop grids.', '["Use repeat(auto-fit, minmax(280px, 1fr)) for responsive card grids","Apply clamp() and @media (min-width: ...) breakpoints"]'::jsonb, 30, '[{"id":"fe42-1","type":"code","title":"Auto-Responsive Grid Without Breakpoint Clutter","language":"css","code":".services-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));\n  gap: 20px;\n}\n\n.hero-title {\n  font-size: clamp(1.85rem, 3.5vw, 3rem);\n}"},{"id":"fe42-2","type":"knowledge_check","prompt":"What does minmax(260px, 1fr) inside CSS Grid ensure?","options":["Columns shrink below 260px on desktop","Each column is at least 260px wide and shares extra space equally","Only 2 columns can ever render"],"correctIndex":1,"explanation":"minmax(260px, 1fr) guarantees cards never squish narrower than 260px while stretching evenly to fill remaining row width."}]'::jsonb, '[]'::jsonb, 'Modern CSS Grid + clamp() handles most responsive adaptation with minimal media-query complexity.', '["Design mobile layouts first, then expand with min-width queries","Avoid fixed pixel heights on text cards"]'::jsonb, '[{"title":"MDN: CSS Grid Layout","url":"https://developer.mozilla.org/en-US/docs/Web/CSS/CSS_grid_layout"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('100e6071-6c3a-4d52-3dca-fdbe74f2af5a'::uuid, '420b4329-9c17-0c00-c0fd-c951a1cc859a'::uuid, 1, 'Values, Scope, Conditionals, and Functions', 'JavaScript turns static documents into responsive software by expressing clear rules and reusable data transformations.', '["Prefer const by default and let only when reassigning","Use strict equality (===) and early returns"]'::jsonb, 25, '[{"id":"fe51-1","type":"paragraph","text":"Strict equality (===) checks both value and type, preventing subtle coercion bugs like \"5\" == 5 returning true. Writing small, single-purpose functions with early guard returns keeps logic readable."},{"id":"fe51-2","type":"code","title":"Pure Discount Calculator Function","language":"javascript","code":"function calculatePackageTotal(basePrice, quantity = 1) {\n  if (basePrice < 0 || quantity < 1) return 0;\n  const subtotal = basePrice * quantity;\n  return quantity >= 3 ? Math.round(subtotal * 0.9) : subtotal;\n}"}]'::jsonb, '[]'::jsonb, 'Clean variable scoping and guard clauses eliminate common state mutation errors.', '["Default to const over let","Always use === and !== for comparisons"]'::jsonb, '[{"title":"MDN: JavaScript First Steps","url":"https://developer.mozilla.org/en-US/docs/Learn/JavaScript/First_steps"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('0395e2c4-0509-85a6-2916-007f5702ada3'::uuid, '420b4329-9c17-0c00-c0fd-c951a1cc859a'::uuid, 2, 'Objects, Arrays, and Declarative Array Methods', 'Real web applications store lists of products, bookings, or lessons as arrays of objects and transform them into UI output.', '["Model domain entities cleanly with objects","Use filter, map, and find rather than manual index mutations"]'::jsonb, 30, '[{"id":"fe52-1","type":"code","title":"Filtering and Summarising Services","language":"javascript","code":"const services = [\n  { id: 1, name: \"Brand Audit\", category: \"Strategy\", price: 450 },\n  { id: 2, name: \"Landing Page\", category: \"Web\", price: 1200 },\n  { id: 3, name: \"Speed Fix\", category: \"Web\", price: 600 }\n];\n\nconst webServices = services.filter((item) => item.category === \"Web\");\nconst webTotal = webServices.reduce((sum, item) => sum + item.price, 0);"},{"id":"fe52-2","type":"knowledge_check","prompt":"Which array method returns a brand-new array containing only items that match a predicate?","options":[".forEach()",".filter()",".sort()"],"correctIndex":1,"explanation":".filter() creates a new array of matching elements without mutating the original array (.sort() mutates in place!)."}]'::jsonb, '[]'::jsonb, 'Declarative .filter(), .map(), and .reduce() chains form the backbone of UI data rendering.', '["Never mutate source arrays directly with .sort() without copying via .slice()","Destructure object properties cleanly in callbacks"]'::jsonb, '[{"title":"MDN: Array.prototype.map()","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/map"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('e4584cfb-2c49-aa78-f655-5eadd9d5a6af'::uuid, 'b5b3aedb-70a3-ad9b-f3cc-53d5e98b49e8'::uuid, 1, 'Querying Nodes, Events, and Accessible State Updates', 'The DOM API bridges static markup and user interactions like button clicks, filter tabs, and modal toggles.', '["Use querySelector, closest(), and addEventListener cleanly","Synchronise ARIA attributes like aria-expanded during state changes"]'::jsonb, 25, '[{"id":"fe61-1","type":"code","title":"Accessible Toggle Pattern","language":"javascript","code":"const toggleBtn = document.querySelector(\"#menu-toggle\");\nconst navDrawer = document.querySelector(\"#mobile-nav\");\n\ntoggleBtn?.addEventListener(\"click\", () => {\n  const isOpen = navDrawer.classList.toggle(\"is-open\");\n  toggleBtn.setAttribute(\"aria-expanded\", String(isOpen));\n});"},{"id":"fe61-2","type":"callout","title":"Security Warning: textContent vs innerHTML","text":"Never pass untrusted user input straight into innerHTML—that opens Cross-Site Scripting (XSS) vulnerabilities. Use textContent or a strict HTML escaping helper for all dynamic strings."}]'::jsonb, '[]'::jsonb, 'Event listeners paired with clean state toggles keep UI behaviour predictable and accessible.', '["Always check if an element exists before binding listeners","Update aria-expanded / aria-pressed alongside CSS classes"]'::jsonb, '[{"title":"MDN: Introduction to the DOM","url":"https://developer.mozilla.org/en-US/docs/Web/API/Document_Object_Model/Introduction"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('79752d11-d441-34c2-f078-42675c83fe13'::uuid, 'b5b3aedb-70a3-ad9b-f3cc-53d5e98b49e8'::uuid, 2, 'Event Delegation & Dynamic Rendering Loops', 'Instead of binding hundreds of listeners to list items, attach one delegated listener to a stable parent container.', '["Use e.target.closest(\"[data-action]\") for delegated clicks","Re-render state-driven UI fragments without duplicating listeners"]'::jsonb, 25, '[{"id":"fe62-1","type":"paragraph","text":"Event bubbling means clicks inside a child button travel upward to its parent container. Listening on the container with e.target.closest(\"[data-filter]\") lets you re-render buttons freely without leaking memory or forgetting to rebind."}]'::jsonb, '[]'::jsonb, 'State -> Render -> Delegated Event Handler is the cleanest architecture for vanilla JS apps.', '["Keep application state in JS variables, not hidden inside DOM text","Delegate clicks via closest() on container elements"]'::jsonb, '[{"title":"MDN: Event Bubbling","url":"https://developer.mozilla.org/en-US/docs/Learn/JavaScript/Building_blocks/Event_bubbling"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('dca59952-93be-93d4-2974-717be7ca6426'::uuid, 'fd887f97-0b99-8407-d9b7-28bc23d4f741'::uuid, 1, 'Accessible Form Structure & Native Input Types', 'A well-structured form improves mobile typing ergonomics and screen-reader clarity before JavaScript even runs.', '["Use semantic input types (email, tel, url, number)","Never replace visible labels with placeholder text"]'::jsonb, 20, '[{"id":"fe71-1","type":"bullets","title":"Non-Negotiable Form Accessibility Rules","items":["Pair every input with an explicit <label for=\"id\">.","Use type=\"email\" or inputmode=\"tel\" so mobile users get the right keyboard.","Provide clear inline error text adjacent to the failing field, never colour alone."]}]'::jsonb, '[]'::jsonb, 'Semantic input types + explicit labels make forms effortless on both desktop and mobile.', '["Placeholders disappear when typing—keep labels visible","Group radio options inside <fieldset> and <legend>"]'::jsonb, '[{"title":"MDN: Your First Form","url":"https://developer.mozilla.org/en-US/docs/Learn/Forms/Your_first_web_form"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('9e861047-e1d9-e985-cc06-ca10f61d4441'::uuid, 'fd887f97-0b99-8407-d9b7-28bc23d4f741'::uuid, 2, 'Client-Side Validation & Helpful Error Messaging', 'Custom JavaScript validation prevents confusing browser popups and gives learners and customers immediate corrective guidance.', '["Intercept submit events with e.preventDefault()","Display field-specific error feedback and clear errors on input"]'::jsonb, 25, '[{"id":"fe72-1","type":"code","title":"Clean Form Validation Flow","language":"javascript","code":"form.addEventListener(\"submit\", (e) => {\n  e.preventDefault();\n  const email = form.email.value.trim();\n  const msg = form.message.value.trim();\n  const errors = {};\n  if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email)) errors.email = \"Enter a valid email address.\";\n  if (msg.length < 20) errors.message = \"Tell us a little more (20+ characters).\";\n  renderFieldErrors(errors);\n});"}]'::jsonb, '[]'::jsonb, 'Immediate, specific, non-judgmental error messages measurably lift form completion rates.', '["Clear field errors as soon as the user begins correcting them","Never rely solely on client validation for security-sensitive actions"]'::jsonb, '[{"title":"MDN: Client-Side Form Validation","url":"https://developer.mozilla.org/en-US/docs/Learn/Forms/Form_validation"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('800e6f8e-598e-1bb3-46f3-5ab9ce0b1384'::uuid, 'd4e2b59d-c916-e976-6b79-4d636f308e48'::uuid, 1, 'Metadata, Asset Optimisation, and Pre-Launch QA', 'A great frontend project is verified across real screen sizes, slow networks, and keyboard-only navigation before shipping.', '["Write accurate <title> and <meta name=\"description\"> tags","Compress imagery and set descriptive Open Graph metadata"]'::jsonb, 25, '[{"id":"fe81-1","type":"table","title":"Pre-Launch Quality Checklist","headers":["Check Area","What to Verify","Target Outcome"],"rows":[["Responsiveness","375px, 768px, and 1440px viewports","Zero horizontal overflow or clipped buttons"],["Accessibility","Tab navigation & contrast ratio","Visible focus rings and >= 4.5:1 text contrast"],["Performance","Image sizes & broken links","Compressed images and zero 404 console errors"]]}]'::jsonb, '[]'::jsonb, 'Structured pre-launch QA catches broken asset paths and mobile layout issues before visitors see them.', '["Check DevTools Console for zero 404s or JS errors","Test all navigation links and form states on mobile width"]'::jsonb, '[{"title":"MDN: Publishing Your Website","url":"https://developer.mozilla.org/en-US/docs/Learn/Getting_started_with_the_web/Publishing_your_website"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('d10ff81d-6546-aea1-03f6-1ee2c60c82f9'::uuid, 'd4e2b59d-c916-e976-6b79-4d636f308e48'::uuid, 2, 'Deploying Static Sites & Managing Clean Releases', 'Modern static hosts (GitHub Pages, Netlify, Cloudflare Pages, Vercel) serve HTML/CSS/JS over global CDNs in minutes.', '["Push clean repository commits with a helpful README","Deploy to a public HTTPS URL and verify live links post-deploy"]'::jsonb, 25, '[{"id":"fe82-1","type":"steps","title":"Clean Static Deployment Workflow","items":["Verify index.html lives at the repository root or configured dist/ folder.","Use relative paths (./styles/main.css) so sub-path hosts like GitHub Pages resolve assets cleanly.","Push to main, enable Pages/CDN deployment, and test the live HTTPS URL in an incognito window."]}]'::jsonb, '[]'::jsonb, 'Always verify the deployed live URL in a fresh browser window—never assume local paths automatically match production.', '["Verify relative CSS/image paths after deployment","Keep repository README clear with setup and architecture notes"]'::jsonb, '[{"title":"GitHub Pages Quickstart","url":"https://docs.github.com/en/pages/quickstart"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('b0ac8efb-69ee-7b2e-3fb4-8e7e19587341'::uuid, '31078ffa-e680-0e73-5784-4bc0204f658f'::uuid, 1, 'Visual Communication vs Decoration', 'Graphic design exists to clarify ideas, guide attention, and prompt human action—not simply to fill empty space with ornaments.', '["Explain the purpose of visual communication across print and screen","Identify the three questions every design brief must answer"]'::jsonb, 25, '[{"id":"gd11-1","type":"heading","text":"Designing With Intent"},{"id":"gd11-2","type":"paragraph","text":"Before picking colours or software, a designer clarifies who the viewer is, what single takeaway must land within three seconds, and what medium will carry the work (print A5 flyer, 1080x1350 social post, or wide web banner)."},{"id":"gd11-3","type":"definition","term":"The Three-Second Read","meaning":"The instant visual scan in which a viewer recognises who is speaking, what is being offered, and where to act next."},{"id":"gd11-4","type":"knowledge_check","prompt":"What is the very first step before choosing fonts or colours for a promotional flyer?","options":["Download decorative icons","Clarify the audience, single core message, and physical format","Apply drop shadows to every heading"],"correctIndex":1,"explanation":"Brief clarity drives every typographic, colour, and layout decision downstream."}]'::jsonb, '[]'::jsonb, 'Strong graphic design solves a communication problem clearly before adding visual flair.', '["Every element on a canvas must earn its place","Define audience + core message + format before sketching"]'::jsonb, '[{"title":"Interaction Design Foundation: Visual Design Basics","url":"https://www.interaction-design.org/literature/topics/graphic-design"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('8d3c9d89-01e9-56d4-792d-c7e46c78d09b'::uuid, '31078ffa-e680-0e73-5784-4bc0204f658f'::uuid, 2, 'From Thumbnail Sketches to Vector Concepts', 'Rapid paper thumbnail sketches protect you from getting locked into your first weak software layout.', '["Sketch 4–6 distinct layout thumbnails in under 10 minutes","Test hierarchy at small scale before opening a digital tool"]'::jsonb, 20, '[{"id":"gd12-1","type":"steps","title":"5-Minute Thumbnail Sprint","items":["Draw six small 4cm boxes on paper.","Block headline, focal visual, date/venue, and CTA using simple rectangles and thick bars.","Pick the two strongest compositions with clearest contrast and breathing room."]}]'::jsonb, '[]'::jsonb, 'Small-scale thumbnailing exposes weak focal hierarchy instantly.', '["Never skip rough layout exploration","Squint test: if major blocks blur into one grey smudge, increase scale contrast"]'::jsonb, '[{"title":"AIGA: Design Process Fundamentals","url":"https://www.aiga.org/resources"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('6d2721b2-5692-032b-97f3-9c0ff5adea45'::uuid, '5cb69c74-cde2-63c7-9eff-99d475b442fe'::uuid, 1, 'Line, Shape, Scale, and Visual Weight', 'Visual weight determines where a viewer looks first, second, and third across any canvas.', '["Identify how size, darkness, isolation, and shape create weight","Use directional lines and containers sparingly"]'::jsonb, 25, '[{"id":"gd21-1","type":"paragraph","text":"Large dark elements carry heavy visual weight; small light elements carry less. Placing a bold geometric headline beside calm open paper draws instant attention without needing neon stickers or loud arrows."},{"id":"gd21-2","type":"bullets","title":"Six Core Elements","items":["Line: guides movement and separates sections subtly","Shape: geometric precision vs organic warmth","Scale: contrast between hero elements and quiet details","Space: active breathing room that frames subject matter","Texture: subtle paper grain or tactile surface depth","Value: lightness-to-darkness range creating legibility"]}]'::jsonb, '[]'::jsonb, 'Contrast in scale and value establishes effortless visual order.', '["Scale contrast beats uniform medium-sized blocks","Hairline dividers whisper; generous margins breathe"]'::jsonb, '[{"title":"Canva Design School: Elements of Design","url":"https://www.canva.com/learn/design-elements-principles/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('23b78877-7535-3648-f5f4-fc06e9fa65cf'::uuid, '5cb69c74-cde2-63c7-9eff-99d475b442fe'::uuid, 2, 'Mastering Negative Space (Whitespace)', 'Whitespace is not wasted empty paper—it is an active structural element that creates focus, elegance, and calm comprehension.', '["Distinguish macro whitespace (outer margins) from micro whitespace (line and card spacing)","Eliminate decorative clutter competing with the main CTA"]'::jsonb, 20, '[{"id":"gd22-1","type":"callout","title":"Resist Filling Every Corner","text":"Crowding text right up to the page edges makes flyers look cheap and hard to scan. Increase outer page margins before shrinking body copy."}]'::jsonb, '[]'::jsonb, 'Generous margins and clear groupings communicate confidence and professionalism.', '["Outer padding should always exceed or equal inner item spacing","Group related details closely (Proximity) and separate unrelated groups"]'::jsonb, '[{"title":"Laws of UX: Law of Proximity","url":"https://lawsofux.com/law-of-proximity/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('38ca110b-a5d7-f9b0-a430-fa9bc22d2f10'::uuid, '72747bc7-f08d-7150-456f-63ed8621c540'::uuid, 1, 'Hue, Value, Saturation & the 60-30-10 Palette Rule', 'Amateur designs fail most often from using five competing saturated colours at equal brightness.', '["Control saturation vs value cleanly","Apply 60% neutral canvas, 30% structural tone, 10% accent discipline"]'::jsonb, 25, '[{"id":"gd31-1","type":"table","title":"The 60-30-10 Colour Allocation Model","headers":["Share","Role","Typical Selection"],"rows":[["60%","Dominant canvas","Crisp off-white, warm cream, or deep slate"],["30%","Structural framing & typography","Charcoal ink, muted slate, light surface cards"],["10%","High-intent focal accent","One vibrant cobalt, terracotta, or emerald CTA/highlight"]]},{"id":"gd31-2","type":"knowledge_check","prompt":"Why should bright accent colours be limited to ~10% of a composition?","options":["Because printers run out of ink","So focal actions stand out immediately against calm neutrals","Because browsers block more than two colours"],"correctIndex":1,"explanation":"When everything is bright and loud, nothing stands out. Restraint creates focal power."}]'::jsonb, '[]'::jsonb, 'Restrained palettes make focal accents unmistakable and keep text calm to read.', '["Neutralise 60% of the canvas so your 10% accent pops","Check value contrast in grayscale to confirm hierarchy"]'::jsonb, '[{"title":"WebAIM Contrast Checker","url":"https://webaim.org/resources/contrastchecker/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('eaa961f9-27d5-e504-c5d7-346b0d847786'::uuid, '72747bc7-f08d-7150-456f-63ed8621c540'::uuid, 2, 'RGB vs CMYK & Accessible Print Contrast', 'Colours emit light on screens (RGB) but absorb light on physical paper ink (CMYK).', '["Convert neon RGB screen expectations safely to printable CMYK gamuts","Test colour-blindness resilience without relying on hue alone"]'::jsonb, 25, '[{"id":"gd32-1","type":"definition","term":"RGB vs CMYK","meaning":"RGB (Red, Green, Blue) is additive light for monitors and phones. CMYK (Cyan, Magenta, Yellow, Key/Black) is subtractive ink used by offset and digital presses."}]'::jsonb, '[]'::jsonb, 'Always proof print colours cleanly and ensure text legibility survives poor lighting and colour vision differences.', '["Neon RGB greens/blues dull when printed in CMYK—test soft-proofs early","Avoid light grey text smaller than 10pt on tinted paper"]'::jsonb, '[{"title":"Adobe: RGB vs CMYK Color Modes","url":"https://www.adobe.com/creativecloud/design/discover/rgb-vs-cmyk.html"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('1df4a4fa-b690-8f11-3be8-a570ac8fdcf7'::uuid, 'a536bd2d-4629-4ffd-e289-1fb96a3701db'::uuid, 1, 'Type Classifications & Confident Font Pairing', 'Typography carries 80% of the tone and clarity in flyers, posters, websites, and editorial layouts.', '["Distinguish Serif, Sans-Serif, Display, and Monospace categories","Pair two distinct fonts cleanly without clashing"]'::jsonb, 25, '[{"id":"gd41-1","type":"paragraph","text":"Effective pairing relies on clear contrast plus shared proportions: for example, pairing an authoritative editorial serif headline (Playfair Display or Fraunces) with a clean humanist sans body (DM Sans or Plus Jakarta Sans), or using a single versatile family in two deliberate weights (700 Bold + 400 Regular)."},{"id":"gd41-2","type":"callout","title":"Maximum Two Fonts Rule","text":"Never mix three or four display fonts on one flyer. Stick to 1–2 font families and create hierarchy through size, weight, and spacing."}]'::jsonb, '[]'::jsonb, 'Limit font families to two and let size contrast do the heavy lifting.', '["Pair contrasting voices—never two nearly identical sans-serifs","Reserve novelty display fonts strictly for short 2–5 word headlines"]'::jsonb, '[{"title":"Google Fonts Knowledge: Typography","url":"https://fonts.google.com/knowledge"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('f41d6b8e-3f05-64e5-7046-98e3599179a9'::uuid, 'a536bd2d-4629-4ffd-e289-1fb96a3701db'::uuid, 2, 'Leading, Tracking, Kerning, and Alignment', 'Small spacing adjustments distinguish hurried amateur layouts from crisp editorial typography.', '["Tighten display headline leading (1.05–1.15) while keeping body leading airy (1.45–1.6)","Left-align multi-line body copy for effortless scanning"]'::jsonb, 25, '[{"id":"gd42-1","type":"definition","term":"Leading vs Tracking","meaning":"Leading is vertical distance between baselines of text; tracking is uniform horizontal spacing across a group of characters."}]'::jsonb, '[]'::jsonb, 'Tighten big headlines slightly, give body paragraphs room to breathe, and prefer clean left alignment.', '["Never apply heavy positive letter-spacing to lowercase body text","Left-aligned text anchors the reader’s eye reliably on every new line"]'::jsonb, '[{"title":"Practical Typography: Line Spacing","url":"https://practicaltypography.com/line-spacing.html"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('3fd2ab5c-4767-ec41-b595-9937cb398a34'::uuid, '649489f2-ad65-af24-188f-a3aa20b13aa2'::uuid, 1, 'Grid Systems, Columns, and Alignment Discipline', 'Grids create invisible architecture so diverse photographs, headlines, and event times feel effortlessly unified.', '["Set up symmetrical margins and 4/6/12-column grids","Align disparate elements along shared vertical axes"]'::jsonb, 25, '[{"id":"gd51-1","type":"paragraph","text":"Every item you place on a page should align with at least one other item on the canvas. Shared left edges create calm structural rhythm even when visual styles vary."}]'::jsonb, '[]'::jsonb, 'Invisible grid lines make layouts look crisp before the viewer even notices why.', '["Match outer page margin width across all four sides (or generous bottom)","Snap images and text blocks cleanly to column tracks"]'::jsonb, '[{"title":"Design Systems Handbook: Layout & Grids","url":"https://www.designbetter.co/design-systems-handbook"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('bef8107c-71e8-0c47-9fd6-40062d64c688'::uuid, '649489f2-ad65-af24-188f-a3aa20b13aa2'::uuid, 2, 'Visual Hierarchy & Focal Entry Points', 'Hierarchy tells viewers what to read first, second, and third without conscious effort.', '["Establish clear primary, secondary, and tertiary reading levels","Avoid two rival focal points fighting at equal size"]'::jsonb, 25, '[{"id":"gd52-1","type":"steps","title":"Testing Hierarchy with the Five-Foot Rule","items":["Step back 5 feet (or zoom out to 25%).","Verify the main headline and key visual still dominate.","Check that date/offer details read cleanly at medium zoom.","Ensure supporting fine print stays neatly grouped at the footer."]}]'::jsonb, '[]'::jsonb, 'A single clear hero anchor makes every promotional piece dramatically easier to scan.', '["One hero visual or bold headline beats three competing banners","Group action details (date, venue, URL/QR) near the bottom-right exit point"]'::jsonb, '[{"title":"Nielsen Norman Group: Visual Hierarchy","url":"https://www.nngroup.com/articles/visual-hierarchy-ux-definition/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('51247b0a-a9d9-6941-c32c-187fa978a5dc'::uuid, '01eaf2c3-097d-3b9f-0c1d-97df91122f34'::uuid, 1, 'Brand Positioning, Voice, and Visual Consistency', 'A brand is not just a logo—it is the consistent impression created across every flyer, storefront, website, and packaging box.', '["Translate 3 brand values into concrete font and colour choices","Maintain visual recognition across multiple deliverables"]'::jsonb, 25, '[{"id":"gd61-1","type":"example","title":"Translating Positioning Into Visual Decisions","body":"A neighbourhood organic roastery (\"Warm, Craft, Honest\") chooses earthy unbleached cream paper, classic serif display type, and warm terracotta accents—never sterile neon gradients."}]'::jsonb, '[]'::jsonb, 'Cohesive visual choices make small brands look trustworthy and memorable immediately.', '["Logo + typography + colour + photography tone work as one system","Document clear-space rules around logos so they never crowd adjacent edges"]'::jsonb, '[{"title":"Figma Learn: Brand Identity Guide","url":"https://www.figma.com/resource-library/what-is-brand-identity/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('e7d659ba-319c-f564-a616-82795c0cdc60'::uuid, '01eaf2c3-097d-3b9f-0c1d-97df91122f34'::uuid, 2, 'Building Practical Mini Brand Guidelines', 'Even a simple 1-page brand sheet prevents mismatched fonts and off-brand hues across marketing campaigns.', '["Define primary/secondary logo usage rules","Specify exact typography hierarchy and colour ratios"]'::jsonb, 20, '[{"id":"gd62-1","type":"bullets","title":"Checklist for a 1-Page Brand Kit","items":["Primary horizontal & stacked mark variants","Primary 60-30-10 colour hex + CMYK values","Display & body font names with size ratios","Do/Don’t rules (no stretching, no low-contrast overlays)"]}]'::jsonb, '[]'::jsonb, 'Mini style guides turn one-off designs into repeatable brand systems.', '["Never stretch or distort a logo aspect ratio","Always keep light/dark versions of marks ready"]'::jsonb, '[{"title":"Canva: Brand Kit Essentials","url":"https://www.canva.com/learn/brand-guidelines/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('299ce0be-ba21-cbfc-f0e0-e1550c467a6a'::uuid, 'd1af902a-0525-a077-325b-48ae16152342'::uuid, 1, 'Vector vs Raster Graphics & Resolution (DPI/PPI)', 'Understanding mathematical vectors versus pixel grids prevents blurry printed flyers and giant bloated web exports.', '["Distinguish resolution-independent vector art from 300 DPI print rasters","Avoid upscaling low-resolution web thumbnails for print"]'::jsonb, 25, '[{"id":"gd71-1","type":"table","title":"Vector vs Raster Quick Reference","headers":["Format Type","How Stored","Best Use Case"],"rows":[["Vector (SVG, AI, PDF)","Mathematical paths and curves","Logos, icons, typography, scalable print layouts"],["Raster (PNG, JPG, WebP)","Fixed grid of coloured pixels","Photography and complex painterly textures (300 DPI for print, 72–144 PPI for screen)"]]}]'::jsonb, '[]'::jsonb, 'Keep logos and text crisp as vectors; ensure embedded photographs have sufficient pixel resolution.', '["Print photos require 300 DPI at physical output size","Never rasterise flyer typography unnecessarily before export"]'::jsonb, '[{"title":"Adobe: Vector vs Raster Files","url":"https://www.adobe.com/creativecloud/file-types/image/comparison/raster-vs-vector.html"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('abdd6401-db02-0e20-51f4-6545945ce0de'::uuid, 'd1af902a-0525-a077-325b-48ae16152342'::uuid, 2, 'Layer Hygiene, Styles, and Non-Destructive Workflows', 'Cleanly named groups and shared styles let you revise client colours or event dates in seconds instead of hunting through 80 unnamed layers.', '["Name layer groups semantically","Use frames, masks, and reusable text/colour styles"]'::jsonb, 20, '[{"id":"gd72-1","type":"paragraph","text":"Group elements by reading zone (Header Mark, Hero Visual, Event Details, CTA Footer) and mask photographs inside frames rather than cropping destructively."}]'::jsonb, '[]'::jsonb, 'Structured layers and reusable styles accelerate feedback revisions.', '["Mask photos non-destructively inside containers","Lock background guides before moving foreground text"]'::jsonb, '[{"title":"Figma Help: Masks and Frames","url":"https://help.figma.com/hc/en-us/articles/360040450253-Masks"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('14cad72f-1a35-5e3a-f557-6949e8ba5e46'::uuid, '70274843-cdb0-65d3-eec9-1e9773769b27'::uuid, 1, 'Bleed, Trim Marks, Safe Margins, and Print Pre-Flight', 'Physical printing presses guillotine stacks of paper—bleed and safe zones prevent ugly white slivers or chopped headlines.', '["Extend edge-to-edge backgrounds 3mm beyond trim edge","Keep critical text at least 6–10mm inside the trim line"]'::jsonb, 25, '[{"id":"gd81-1","type":"definition","term":"Bleed & Safe Zone","meaning":"Bleed is extra background artwork (typically 3mm / 0.125in) extending past the final cut line. The Safe Zone keeps all text comfortably inside the trim line."},{"id":"gd81-2","type":"knowledge_check","prompt":"Why must edge-to-edge background photos extend 3mm beyond the document trim border?","options":["To make the file heavier","So slight paper cutting shifts never leave an unintended white border strip","To double image DPI"],"correctIndex":1,"explanation":"Mechanical paper cutters vary by ~1mm; 3mm bleed guarantees clean edge-to-edge ink after trimming."}]'::jsonb, '[]'::jsonb, 'Proper bleed, embedded fonts, and safe margins separate print-ready artwork from rejected press files.', '["Always check 100% zoom before final export","Include crop marks and bleed for commercial print PDFs"]'::jsonb, '[{"title":"Printivity: What Is Bleed?","url":"https://www.printivity.com/insights/what-is-bleed-in-printing/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('1d33a098-a032-bfb7-81c1-f5cd8dd7c496'::uuid, '70274843-cdb0-65d3-eec9-1e9773769b27'::uuid, 2, 'Export Formats & Presenting Your Design Rationale', 'Clients and stakeholders approve stronger work when you explain the audience, hierarchy, and colour choices behind your layout.', '["Select the right export format (PDF Print, PNG, JPG, SVG)","Summarise design decisions clearly in a 1-paragraph rationale"]'::jsonb, 20, '[{"id":"gd82-1","type":"steps","title":"Presenting Work Professionally","items":["State the business goal and audience first.","Explain how typography scale guides the 3-second read.","Explain why your 60-30-10 palette reinforces brand mood and contrast."]}]'::jsonb, '[]'::jsonb, 'Export cleanly for both physical and screen contexts, and articulate your visual reasoning clearly.', '["Use PNG/WebP for crisp digital UI graphics and PDF for print","Tie visual choices back to audience readability and business goal"]'::jsonb, '[{"title":"NN/g: Presenting Design Work","url":"https://www.nngroup.com/articles/presenting-design/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('cd38fdd0-3e06-a6a6-5776-e9e888c6cd0f'::uuid, '6ee2ae2b-51e5-30da-6985-df81dcd26c65'::uuid, 1, 'The Digital Marketing Funnel & Media Trifecta', 'Random social posting wastes effort because different stages of buyer readiness require different messages and offers.', '["Explain Awareness, Consideration, Conversion, and Retention","Balance Owned, Earned, and Paid channels sustainably"]'::jsonb, 25, '[{"id":"dm11-1","type":"heading","text":"Owned, Earned, and Paid Media"},{"id":"dm11-2","type":"table","title":"Channel Categories in Modern Marketing","headers":["Media Type","Examples","Strength & Risk"],"rows":[["Owned","Website, email list, blog, podcast","Full control and zero ad-platform rent; slower to build initially"],["Earned","Word-of-mouth, shares, PR, reviews","Highest trust; requires consistently helpful products and content"],["Paid","Meta Ads, Google Search, sponsored newsletters","Fast targeted reach; stops immediately when budget pauses"]]},{"id":"dm11-3","type":"knowledge_check","prompt":"Why is an email subscriber list classified as Owned Media?","options":["Because social algorithms control every send","Because you own direct permission and distribution independent of social algorithm changes","Because you pay per email read"],"correctIndex":1,"explanation":"Owned media assets (website, email list) protect your business from sudden social reach drops."}]'::jsonb, '[]'::jsonb, 'Great marketing connects paid discovery and social reach directly into owned conversion assets.', '["Every campaign starts with one primary business outcome","Do not build exclusively on rented social platforms"]'::jsonb, '[{"title":"Google Digital Garage: Fundamentals of Digital Marketing","url":"https://skillshop.exceedlms.com/student/catalog"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('75bf489f-2e1a-7e80-19cd-7add43b45f4e'::uuid, '6ee2ae2b-51e5-30da-6985-df81dcd26c65'::uuid, 2, 'Customer Journey Mapping & Value Propositions', 'Before writing copy or buying ads, define the exact friction your customer wants removed and why your solution wins.', '["Write a crisp 1-sentence value proposition","Spot friction gaps between ad promises and landing pages"]'::jsonb, 20, '[{"id":"dm12-1","type":"definition","term":"Message-Match","meaning":"Continuity between the headline/promise in an ad or social post and the immediate hero headline on the landing page."}]'::jsonb, '[]'::jsonb, 'Clear message-match reduces bounce rates faster than tweaking button colours.', '["Match landing page headlines to the link promise","Address top buyer objections transparently"]'::jsonb, '[{"title":"HubSpot Academy: Inbound Methodology","url":"https://academy.hubspot.com/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('a83a8cac-7432-117d-6226-52be994aeabc'::uuid, '4fbbb134-2d0a-2a8f-0cd3-2e5d2da2f1ac'::uuid, 1, 'Jobs-to-Be-Done & Voice-of-Customer Mining', 'Demographics ("Women 25–40") never explain why someone buys; specific life triggers and frustrations do.', '["Separate superficial demographics from buying triggers","Extract persuasive hooks directly from customer reviews"]'::jsonb, 25, '[{"id":"dm21-1","type":"example","title":"Demographic vs Trigger-Based Persona","body":"Weak: \"Small business owners aged 30–50.\"\nStrong: \"Solo clinic founders losing 4+ hours a week to manual appointment reminders and last-minute no-shows.\""}]'::jsonb, '[]'::jsonb, 'When you describe a buyer’s frustration better than they can, they immediately trust your solution.', '["Mine 1-star and 4-star competitor reviews for honest buyer priorities","Anchor every persona in triggers, desired outcomes, and objections"]'::jsonb, '[{"title":"SparkToro: Audience Research Guide","url":"https://sparktoro.com/blog/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('1c9d9cfb-5b84-4624-753a-c9ef2aab4e94'::uuid, '4fbbb134-2d0a-2a8f-0cd3-2e5d2da2f1ac'::uuid, 2, 'Segmentation & Search Intent Signals', 'Not every visitor is ready to buy today—segment cold learners cleanly from high-intent comparison shoppers.', '["Classify Informational, Comparative, and Transactional intent","Tailor offers cleanly to awareness level"]'::jsonb, 20, '[{"id":"dm22-1","type":"bullets","title":"Three Intent Tiers","items":["Informational: \"how to reduce bakery food waste\" -> Offer checklist/guide","Comparative: \"best POS system for cafes UK\" -> Offer comparison matrix","Transactional: \"book commercial espresso repair London\" -> Direct booking form"]}]'::jsonb, '[]'::jsonb, 'Aligning offer depth with buyer intent stops aggressive hard-selling to cold readers.', '["Cold audiences convert better on low-friction guides or audits","High-intent searchers want transparent pricing and fast booking"]'::jsonb, '[{"title":"Ahrefs: Search Intent Explained","url":"https://ahrefs.com/blog/search-intent/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('c7932c7f-db7a-396e-4b68-4218c7b77eb9'::uuid, 'eef6d687-2e34-9aa3-e674-dc02fe223505'::uuid, 1, 'Building Sustainable Content Pillars & Search Value', 'Consistent content marketing answers your audience’s real questions cleanly before asking for a sale.', '["Select 3–4 focused pillars overlapping expertise and customer pain","Avoid generic trend-chasing that attracts non-buyers"]'::jsonb, 25, '[{"id":"dm31-1","type":"paragraph","text":"Every brand needs only 3–4 clear pillars: (1) How-to tutorials solving immediate headaches, (2) Behind-the-scenes proof & case studies, (3) Myth-busting / honest comparisons, and (4) Timely product offers."}]'::jsonb, '[]'::jsonb, 'Focused content pillars build authority faster than random viral topics.', '["Educate specifically around problems your product helps solve","Pair every educational guide with one natural next step"]'::jsonb, '[{"title":"Content Marketing Institute: Getting Started","url":"https://contentmarketinginstitute.com/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('ba355674-df85-6102-af29-13a036df805d'::uuid, 'eef6d687-2e34-9aa3-e674-dc02fe223505'::uuid, 2, 'The 1-to-4 Content Repurposing Workflow', 'Small teams multiply output without burnout by turning one well-researched piece into native formats per channel.', '["Adapt a flagship idea cleanly for email, carousel, short video, and blog","Respect native platform formatting norms"]'::jsonb, 20, '[{"id":"dm32-1","type":"steps","title":"1-to-4 Repurposing Loop","items":["Write one 600-word practical guide or customer teardown.","Extract 5 visual steps into a LinkedIn/Instagram carousel.","Record a 60-second spoken walkthrough.","Send a crisp 150-word email lesson linking back to the full resource."]}]'::jsonb, '[]'::jsonb, 'Repurposing deepens message consistency while cutting production strain in half.', '["Adapt format natively rather than copying identical links everywhere","Track which angles earn saves and replies"]'::jsonb, '[{"title":"Buffer: Content Repurposing Workflow","url":"https://buffer.com/resources/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('05805afd-9f29-e392-50ce-cd3f546f1764'::uuid, '8927aa09-f63d-ace2-96c4-a60f0deee13b'::uuid, 1, 'Channel Selection & Platform-Native Mechanics', 'Each social network rewards distinct user intent—LinkedIn favours professional insights, Instagram carousels/Reels reward saves and shares, and YouTube rewards search depth.', '["Pick channels based on where buyers already spend decision time","Prioritise saves, shares, and meaningful comments over hollow likes"]'::jsonb, 25, '[{"id":"dm41-1","type":"callout","title":"Depth Beats Presence Everywhere","text":"Executing excellently on two well-matched platforms outperforms copying mediocre links across six accounts."}]'::jsonb, '[]'::jsonb, 'Match channel culture and format natively, focusing on saves, shares, and conversations.', '["Optimise first 2 lines above the \"...see more\" fold","Reply actively within the first hour to grow community trust"]'::jsonb, '[{"title":"Hootsuite: Social Media Strategy Guide","url":"https://blog.hootsuite.com/how-to-create-a-social-media-marketing-plan/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('ffdf17d7-66b5-4233-8909-1bdf10f671ee'::uuid, '8927aa09-f63d-ace2-96c4-a60f0deee13b'::uuid, 2, 'Community Engagement & Paid Amplification Basics', 'Organic social validates which messages resonate; targeted paid ads then scale proven creatives systematically.', '["Test hooks organically before putting ad spend behind them","Avoid vanity boost-post habits without conversion tracking"]'::jsonb, 20, '[{"id":"dm42-1","type":"paragraph","text":"Watch which organic posts earn unusually high saves, DMs, or link clicks—those proven hooks become your highest-confidence creative candidates when launching paid campaigns."}]'::jsonb, '[]'::jsonb, 'Let real organic engagement data guide paid campaign creative.', '["Never boost posts blindly without defining target objective and landing page","Build real conversations in DMs and comments"]'::jsonb, '[{"title":"Meta Blueprint: Business Learning","url":"https://www.facebook.com/business/learn"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('8972d7e2-83d3-2e1b-f915-cfcedd359839'::uuid, '5f2f372b-dd2c-ac45-c4dc-55da52b3fdc4'::uuid, 1, 'Clarity Over Cleverness: Features vs Outcomes', 'Confused visitors never buy. Good copywriting states what the product is, who it helps, and what concrete outcome it unlocks.', '["Convert features into customer-facing benefits","Eliminate vague marketing clichés"]'::jsonb, 25, '[{"id":"dm51-1","type":"example","title":"Feature vs Outcome Translation","body":"Feature: \"Automated CSV export every Friday.\"\nOutcome: \"Send your weekly client performance summary in 30 seconds instead of rebuilding spreadsheets every Friday afternoon.\""}]'::jsonb, '[]'::jsonb, 'Specificity builds instant credibility; vague superlatives trigger scepticism.', '["Write how real buyers speak","Lead with clarity before wordplay"]'::jsonb, '[{"title":"Copyhackers: Conversion Copywriting","url":"https://copyhackers.com/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('72c31def-c65c-2f25-647f-b31df9221456'::uuid, '5f2f372b-dd2c-ac45-c4dc-55da52b3fdc4'::uuid, 2, 'AIDA, PAS, and Friction-Free Calls-to-Action', 'Proven narrative structures prevent rambling copy and lead naturally into one unmistakable next step.', '["Apply Problem–Agitate–Solve (PAS) cleanly in short ads and emails","Write specific low-friction CTA labels"]'::jsonb, 25, '[{"id":"dm52-1","type":"definition","term":"PAS Framework","meaning":"Problem (name the reader’s exact pain), Agitate (highlight the cost of leaving it unsolved), Solve (introduce your clear path forward + CTA)."},{"id":"dm52-2","type":"knowledge_check","prompt":"Which button CTA removes ambiguity best on a service site?","options":["Submit","Click Here","Book a Free 15-Min Audit"],"correctIndex":2,"explanation":"Specific CTAs state both the exact action and what the visitor receives next."}]'::jsonb, '[]'::jsonb, 'PAS and clear CTAs give readers effortless momentum from hook to action.', '["Keep one primary CTA per email or section","State clearly what happens after clicking"]'::jsonb, '[{"title":"NN/g: Writing Effective CTAs","url":"https://www.nngroup.com/articles/call-to-action-buttons/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('465e98f7-fb84-9862-702e-584a9e0e4b49'::uuid, '114e11c2-a54b-c081-a03a-cb36e2526054'::uuid, 1, 'Architecting a 7-Day Integrated Campaign Arc', 'Single posts get forgotten within hours; a structured 7-day sequence builds curiosity, addresses proof and objections, and closes cleanly.', '["Sequence Warm-Up, Proof, Objection-Handling, and Deadline days","Coordinate social, email, and landing page messaging"]'::jsonb, 25, '[{"id":"dm61-1","type":"table","title":"7-Day Campaign Momentum Blueprint","headers":["Days","Focus","Primary Channels"],"rows":[["Days 1–2","Problem awareness & teaser insight","Social carousel + educational email"],["Days 3–4","Solution reveal & social proof / case study","Landing page + short video + retargeting"],["Days 5–6","FAQ, objection busting & behind-the-scenes","Email + community Q&A"],["Day 7","Final reminder & clear conversion deadline","Direct CTA email + final social story"]]}]'::jsonb, '[]'::jsonb, 'A sequenced campaign answers buyer questions progressively instead of repeating "Buy now!" seven times.', '["Never launch an email or social promo before the destination page is live and tested","Coordinate channel messaging daily"]'::jsonb, '[{"title":"Google Campaign URL Builder","url":"https://ga-dev-tools.google/campaign-url-builder/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('70c27851-127f-8e0f-6757-e32b12776fd8'::uuid, '114e11c2-a54b-c081-a03a-cb36e2526054'::uuid, 2, 'UTM Attribution Hygiene & Launch Readiness', 'Without clean UTM tags, your analytics dashboard groups newsletter clicks and social promos under "Direct / Unknown".', '["Standardise utm_source, utm_medium, and utm_campaign","Verify mobile checkout/form completion end-to-end before Day 1"]'::jsonb, 20, '[{"id":"dm62-1","type":"code","title":"Clean Tagged Link Example","language":"text","code":"https://harbourbakery.example/spring-box?utm_source=instagram&utm_medium=social&utm_campaign=spring_launch_2026"}]'::jsonb, '[]'::jsonb, 'Clean UTM tagging guarantees you know exactly which day and channel drove real results.', '["Never put UTM parameters on internal website links","Test every tagged link on mobile before scheduling"]'::jsonb, '[{"title":"Google Analytics: Campaign Attribution","url":"https://support.google.com/analytics/answer/10917952"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('2cef8647-7817-2a65-cb6c-fa2ae489b6fb'::uuid, '9f52fbd6-9d99-0385-cee9-e5387e33ec33'::uuid, 1, 'Actionable KPIs vs Vanity Metrics', 'Impressions and page views feel reassuring, yet revenue and qualified leads determine whether marketing actually works.', '["Compute CTR, CVR, CPA, and ROAS from raw numbers","Tie every metric to a clear decision"]'::jsonb, 25, '[{"id":"dm71-1","type":"table","title":"Core Funnel Diagnostics","headers":["Metric","Formula","What Low Performance Means"],"rows":[["CTR (Click-Through Rate)","Clicks / Impressions × 100","Weak hook, unclear creative, or mismatched audience"],["CVR (Conversion Rate)","Conversions / Landing Visits × 100","Slow page, broken message-match, or unclear offer"],["CPA (Cost Per Acquisition)","Total Spend / Conversions","Unit economics unsustainable unless CVR or AOV rises"]]}]'::jsonb, '[]'::jsonb, 'Inspecting pairs of metrics reveals immediately whether to fix the ad hook or the landing page.', '["High CTR + low CVR usually signals a landing page or offer issue","Low CTR + high CVR means the offer converts well once clicked—scale better hooks"]'::jsonb, '[{"title":"Google Analytics 4 Skillshop","url":"https://skillshop.withgoogle.com/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('619b21d7-70e4-d5bf-75a4-79d1af67e457'::uuid, '9f52fbd6-9d99-0385-cee9-e5387e33ec33'::uuid, 2, 'Attribution Windows & Honest Performance Reporting', 'Buyers rarely convert on their very first click; responsible reporting explains assumptions cleanly.', '["Distinguish first-click vs last-click attribution","Present weekly performance using Bottom-Line-Up-Front clarity"]'::jsonb, 20, '[{"id":"dm72-1","type":"paragraph","text":"Report weekly findings with three crisp numbers upfront (Spend, Qualified Leads/Sales, CPA/ROAS), followed by one diagnosed bottleneck and the next concrete test."}]'::jsonb, '[]'::jsonb, 'Transparent reporting builds stakeholder confidence even during testing weeks.', '["Pair relative percentages with raw volume counts","Document external changes (pricing, outages) beside trend charts"]'::jsonb, '[{"title":"Avinash Kaushik: Occam’s Razor Analytics","url":"https://www.kaushik.net/avinash/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('30961c63-888c-f510-0a52-d5b2a336cedb'::uuid, '9fb320ae-27f3-b05e-789b-a184bc9e631a'::uuid, 1, 'Hypothesis-Driven A/B Testing & Sample Discipline', 'Changing five elements simultaneously leaves you unable to tell which change helped—or hurt.', '["Isolate one independent variable per test","Write crisp If/Then/Because test hypotheses"]'::jsonb, 25, '[{"id":"dm81-1","type":"example","title":"Clean Experiment Hypothesis","body":"If we change our landing headline from \"Modern Dental Care\" to \"Same-Week Gentle Checkups with Transparent Fixed Pricing\", then booking clicks will increase because anxious patients value predictable cost and speed."}]'::jsonb, '[]'::jsonb, 'Structured experiments turn campaign losses into compounding customer insights.', '["Wait for meaningful conversion volume before declaring a winner","Document losing tests so teams never repeat them"]'::jsonb, '[{"title":"Optimizely: A/B Testing Glossary","url":"https://www.optimizely.com/optimization-glossary/ab-testing/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('786f25b3-cfd6-0181-89e7-1ea45ac9780c'::uuid, '9fb320ae-27f3-b05e-789b-a184bc9e631a'::uuid, 2, 'Diagnosing Creative Fatigue & Budget Reallocation', 'Even winning ads and social formats tire out once core audiences have seen them repeatedly.', '["Spot rising Frequency + falling CTR as fatigue signals","Refresh hooks cleanly without resetting winning audience learnings"]'::jsonb, 20, '[{"id":"dm82-1","type":"bullets","title":"Three Signs of Creative Fatigue","items":["Frequency climbs above 3.5–4.0 on prospecting sets","CTR drops steadily across 5 consecutive days","CPC climbs even though landing page CVR stays flat"]}]'::jsonb, '[]'::jsonb, 'Continuous creative refresh keeps acquisition costs stable without constant budget panic.', '["Rotate 2–3 fresh visual hooks before frequency spikes","Shift budget gradually toward verified lower-CPA segments"]'::jsonb, '[{"title":"Meta Business Help: Ad Fatigue","url":"https://www.facebook.com/business/help"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('57cb848d-3a5b-1800-a34a-f18967b6e01a'::uuid, 'a37791dc-3d3a-9c1a-2ea0-d13fe9246459'::uuid, 1, 'The Communication Loop & Reducing Noise', 'Communication is not what you intended to say—it is what your listener actually understood and acted upon.', '["Map Sender -> Encoding -> Channel -> Decoding -> Feedback","Confirm comprehension without sounding patronising"]'::jsonb, 25, '[{"id":"cm11-1","type":"heading","text":"Meaning Lives in the Receiver’s Understanding"},{"id":"cm11-2","type":"paragraph","text":"Every message passes through technical or psychological noise—jargon, rushed context, fatigue, or mismatched expectations. Closing the loop with one simple question (\"What questions or gaps stand out on your side?\") turns one-way broadcasting into real alignment."},{"id":"cm11-3","type":"knowledge_check","prompt":"When is a spoken briefing truly complete?","options":["The instant you finish reading your slides","Once you have verified mutual understanding and agreed next steps","When nobody interrupts"],"correctIndex":1,"explanation":"Silence can signal confusion or disengagement—closing the feedback loop confirms real clarity."}]'::jsonb, '[]'::jsonb, 'Focus on listener comprehension rather than how fluent your script sounds to yourself.', '["State your goal in the first 15 seconds","Replace \"Does that make sense?\" with \"What would you adjust?\""]'::jsonb, '[{"title":"MindTools: Communication Skills Overview","url":"https://www.mindtools.com/page8.html"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('e891d817-821a-f7fc-57b9-f1ada764ad1e'::uuid, 'a37791dc-3d3a-9c1a-2ea0-d13fe9246459'::uuid, 2, 'Active Listening & Clarifying Prompts', 'Strong speakers are perceptive listeners who adapt in real time rather than lecturing blindly.', '["Practise paraphrasing and summarising before replying","Notice unspoken concerns during Q&A"]'::jsonb, 20, '[{"id":"cm12-1","type":"steps","title":"3-Step Active Listening Loop","items":["Listen fully without scripting your rebuttal mid-sentence.","Paraphrase the core point concisely (\"So the main risk is timeline slip in Week 3?\").","Confirm before proposing your response."]}]'::jsonb, '[]'::jsonb, 'Paraphrasing builds instant rapport and prevents solving the wrong question.', '["Pause 1–2 seconds before answering hard questions","Reflect intent calmly before defending your position"]'::jsonb, '[{"title":"HBR: How to Become a Better Listener","url":"https://hbr.org/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('7d4e0259-d96a-2787-9e55-776bd02d49c8'::uuid, 'de26ab8c-a851-617c-5422-c354be6c14a7'::uuid, 1, 'Vocal Variety, Pacing, and the Power of the Pause', 'Monotone speed exhausts listeners; deliberate pauses give audiences half a second to absorb important claims.', '["Hit natural 130–150 words per minute clarity","Replace vocal fillers with silent pauses"]'::jsonb, 25, '[{"id":"cm21-1","type":"definition","term":"The Anchor Pause","meaning":"A clean 1-to-2 second silence immediately before or after a crucial point, letting the room digest your message and signalling calm authority."}]'::jsonb, '[]'::jsonb, 'Silence feels longer inside your own head than it sounds to your audience—trust your pauses.', '["Slow down 15% when nervous","Finish sentences downward rather than trailing into upward questioning tone"]'::jsonb, '[{"title":"Toastmasters: Vocal Variety Guide","url":"https://www.toastmasters.org/resources/public-speaking-tips"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('b85d577f-ea92-5458-f063-7170cce06ad2'::uuid, 'de26ab8c-a851-617c-5422-c354be6c14a7'::uuid, 2, 'Plain Language, Concrete Stories, and Signposting', 'Spoken language must be simpler than written essays because listeners cannot re-read a convoluted sentence.', '["Cut abstract jargon into concrete imagery","Use clear verbal signposts (\"First...\", \"Here is the catch...\", \"To wrap up...\")"]'::jsonb, 20, '[{"id":"cm22-1","type":"example","title":"Written Essay vs Spoken Clarity","body":"Dense: \"We must synergise cross-functional communication efficiencies across quarterly touchpoints.\"\nClear: \"If marketing and engineering meet for 15 minutes every Monday, we will catch launch blockers a week earlier.\""}]'::jsonb, '[]'::jsonb, 'Short sentences and explicit verbal signposts help listeners track your structure effortlessly.', '["One main idea per spoken sentence","Tell listeners where you are going before jumping sections"]'::jsonb, '[{"title":"PlainLanguage.gov Principles","url":"https://www.plainlanguage.gov/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('487d77c8-2667-ee02-8e57-e7b8ba429d40'::uuid, 'ee983d8d-2805-6161-6ecf-c65338897282'::uuid, 1, 'Grounded Stance, Eye Contact, and Open Gestures', 'When spoken words say "We are confident in this plan" while shoulders hunch and hands fidget, audiences trust the body language.', '["Stand balanced hip-width apart without pacing aimlessly","Use natural waist-to-chest gestures aligned with key numbers and contrasts"]'::jsonb, 25, '[{"id":"cm31-1","type":"bullets","title":"Practical Delivery Anchors","items":["Plant both feet cleanly when delivering your opening and closing lines.","Hold eye contact for one complete phrase (3–4 seconds) per listener zone.","Keep gestures open and purposeful; return hands gently to rest rather than gripping pockets."]}]'::jsonb, '[]'::jsonb, 'Calm grounded posture automatically slows racing breath and projects quiet confidence.', '["Pause nervous pacing during crucial takeaways","Gesture slightly higher on video calls so hands stay inside frame"]'::jsonb, '[{"title":"TED: Speaking Body Language Tips","url":"https://ideas.ted.com/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('19df7ab2-6058-d206-c209-d37f9422456d'::uuid, 'ee983d8d-2805-6161-6ecf-c65338897282'::uuid, 2, 'Virtual Presence & Webcam Eye Contact', 'On remote calls, looking directly into the camera lens—rather than your own corner preview—creates genuine connection.', '["Position lens at eye level with soft front lighting","Look at the camera lens during opening hooks and key asks"]'::jsonb, 20, '[{"id":"cm32-1","type":"callout","title":"The Sticky-Note Lens Trick","text":"Stick a small paper arrow right beside your laptop webcam lens as a physical reminder of where your audience’s eyes are during key sentences."}]'::jsonb, '[]'::jsonb, 'Clean lighting, eye-level camera placement, and direct lens focus elevate virtual talks immediately.', '["Face a window or soft front lamp rather than sitting backlit","Place cue cards just beneath the webcam so glancing barely moves your gaze"]'::jsonb, '[{"title":"Stanford Virtual Human Interaction Lab","url":"https://vhil.stanford.edu/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('0f60a6f3-ac76-9eb7-595d-bf03280cccdb'::uuid, '667f0407-11a9-0e7c-1d61-dc368efd2f01'::uuid, 1, 'Understanding Knowledge Gaps, Stakes, and Motivations', 'A brilliant talk pitched at the wrong altitude loses the room in two minutes—too basic insults experts; too dense alienates beginners.', '["Complete a 4-question audience scan before outlining","Identify potential scepticism early"]'::jsonb, 25, '[{"id":"cm41-1","type":"table","title":"Pre-Talk Audience Matrix","headers":["Question","Why It Changes Your Outline"],"rows":[["What do they already know?","Determines how much background to skip"],["What keeps them up at night?","Determines your opening hook and stakes"],["What might they doubt?","Determines which proof or counter-example to include"],["What one action can they actually take?","Determines your closing ask"]]}]'::jsonb, '[]'::jsonb, 'Every minute invested in audience analysis cuts wasted background slides in half.', '["Cut backstory that the audience already knows","Address top scepticism upfront rather than hoping nobody asks"]'::jsonb, '[{"title":"Toastmasters: Know Your Audience","url":"https://www.toastmasters.org/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('7c95b25a-5428-b443-0574-e8aa66e5f3a4'::uuid, '667f0407-11a9-0e7c-1d61-dc368efd2f01'::uuid, 2, 'Framing Technical or Niche Ideas for Broad Rooms', 'Real leadership requires translating specialist details into clear impact without dumbing down accuracy.', '["Use concrete analogies grounded in everyday life","Separate core insight from optional technical appendix details"]'::jsonb, 20, '[{"id":"cm42-1","type":"paragraph","text":"Lead with impact (\"This saves support teams 6 hours a week\"), prove it with one human example, and keep deep technical specs ready for Q&A."}]'::jsonb, '[]'::jsonb, 'Lead with human impact, then offer technical depth for those who ask.', '["Analogy bridges unfamiliar concepts to familiar experience","Keep slide text minimal—you are the presentation, not the projector"]'::jsonb, '[{"title":"Duarte: Audience Empathy Mapping","url":"https://www.duarte.com/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('5c99309f-001e-7d50-0225-45cdd4053357'::uuid, '0094ebe1-50a1-eb7f-a60d-a31d7cf80bbb'::uuid, 1, 'Winning the First 15 Seconds & Rule of Three', 'Audiences decide whether to tune in within your first two sentences—never waste them reading your slide title.', '["Use four proven openers (surprising stat, brief story, vivid question, or bold contrast)","Group supporting arguments into 3 memorable chunks"]'::jsonb, 25, '[{"id":"cm51-1","type":"bullets","title":"Four High-Impact Opening Hooks","items":["A concrete 1-sentence story (\"Last Tuesday at 9am, three customers walked out...\")","A surprising grounded metric","A sharp audience question raising tension","A crisp What-Is vs What-Could-Be contrast"]},{"id":"cm51-2","type":"knowledge_check","prompt":"Why does the \"Rule of Three\" work so reliably in spoken presentations?","options":["Because audiences remember 3 clear clusters far better than 9 disconnected bullet points","Because microphones cut off after three points","Because slides require 3 pages"],"correctIndex":0,"explanation":"Human working memory chunks short sets cleanly; three clear pillars give structure without overload."}]'::jsonb, '[]'::jsonb, 'Open cleanly with an authentic hook and organise the body into three crisp takeaways.', '["Never start by apologising for nerves or poor slides","Use clear transitions between Point 1, Point 2, and Point 3"]'::jsonb, '[{"title":"TEDx Speaker Guide","url":"https://www.ted.com/participate/organize-a-local-tedx-event/tedx-organizer-guide/speakers-program/prepare-your-speaker"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('0f25d74a-07ad-21fc-8119-170bee6dfabd'::uuid, '0094ebe1-50a1-eb7f-a60d-a31d7cf80bbb'::uuid, 2, 'Designing Memorable Conclusions (No "That’s All I Have")', 'Ending with a limp "So yeah, thank you" erases momentum—land your closing takeaway cleanly and stop.', '["Tie your closing line back to your opening hook","Deliver a crisp final call-to-action or reflection before thanking the room"]'::jsonb, 20, '[{"id":"cm52-1","type":"callout","title":"Callback Closing Pattern","text":"Revisit the story or question from your opening 15 seconds, state the single decision or action you want, pause 1 second, and end cleanly."}]'::jsonb, '[]'::jsonb, 'Plan your very last sentence verbatim so you finish with poise.', '["Memorise your opening 2 lines and final 2 lines word-for-word","Stop talking cleanly once your closing line lands"]'::jsonb, '[{"title":"Carmine Gallo: Talk Like TED","url":"https://www.carminegallo.com/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('87086aaa-7a96-4cbb-a0f2-ae804d03e69e'::uuid, '093c960b-d447-0ba6-c2ef-5cf102b861cb'::uuid, 1, 'Ethos, Pathos, and Logos in Modern Persuasion', 'Pure spreadsheets rarely move people to act; pure emotion feels hollow. Persuasive speaking weaves trust, human stakes, and evidence together.', '["Audit any pitch for missing trust, emotion, or evidence legs","Turn dry numbers into human-scale comparisons"]'::jsonb, 25, '[{"id":"cm61-1","type":"table","title":"Three Pillars of Ethical Persuasion","headers":["Pillar","Question It Answers","Practical Example"],"rows":[["Ethos (Trust)","Why should we trust you?","Share direct hands-on experience or honest constraints"],["Pathos (Stakes)","Why should we care today?","Tell a brief story about one real person affected"],["Logos (Evidence)","Why does this actually work?","Show concrete before/after metrics or clear logic"]]}]'::jsonb, '[]'::jsonb, 'Make data vivid with human examples, and ground human stories in real evidence.', '["Acknowledge counter-arguments honestly to boost Ethos","Never exaggerate claims—understatement feels far more credible"]'::jsonb, '[{"title":"Aristotle’s Rhetoric Overview","url":"https://plato.stanford.edu/entries/aristotle-rhetoric/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('eba202b4-0370-f040-a704-fddf26776025'::uuid, '093c960b-d447-0ba6-c2ef-5cf102b861cb'::uuid, 2, 'Handling Challenging Q&A Without Getting Defensive', 'Tough questions are a gift—they reveal exactly what stands between your audience and agreement.', '["Apply Acknowledge -> Answer -> Bridge cleanly","Say \"I will verify and follow up\" honestly when unsure"]'::jsonb, 20, '[{"id":"cm62-1","type":"steps","title":"Handling Hard Questions Calmly","items":["Listen completely without interrupting.","Validate the question’s relevance (\"That budget risk is important to test...\").","Answer concisely in 2–3 sentences anchored to your core evidence."]}]'::jsonb, '[]'::jsonb, 'Calm curiosity during Q&A persuades undecided observers more than polished slides.', '["Never invent statistics on the spot—commit to a follow-up instead","Keep answers under 45 seconds so Q&A stays conversational"]'::jsonb, '[{"title":"HBR: Handling Tough Questions in Presentations","url":"https://hbr.org/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('0c24496c-a51d-1c84-9698-0e2cbbbec8fa'::uuid, '5b22e202-5186-acaa-dd56-23c790c35cf6'::uuid, 1, 'Managing Nerves & Rehearsing Without Sounding Robotic', 'Adrenaline sharpens focus—you do not need zero butterflies, you just need steady breath and conversational familiarity.', '["Practise 4-4-4 breathing before speaking","Use keyword cue cards instead of reading verbatim scripts"]'::jsonb, 25, '[{"id":"cm71-1","type":"paragraph","text":"Memorising a full speech word-for-word sets a fragile trap: forget one word mid-paragraph and your brain freezes. Instead, memorise your outline sequence and key anchor phrases, then speak conversationally around them."}]'::jsonb, '[]'::jsonb, 'Conversational rehearsal with timed checkpoints creates resilient, natural delivery.', '["Rehearse out loud standing up—silent reading in your head is always faster than speaking","Keep water nearby and pause to breathe if you lose your thread"]'::jsonb, '[{"title":"Toastmasters: Overcoming Nervousness","url":"https://www.toastmasters.org/resources/public-speaking-tips"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('392648b2-0ef1-013a-ccb1-52c13a1c9c74'::uuid, '5b22e202-5186-acaa-dd56-23c790c35cf6'::uuid, 2, 'Recording Clean Audio & Video Practice Takes', 'Reviewing a two-minute recording of yourself reveals habits—fast pacing, filler words, posture—invisible while speaking.', '["Set up clear microphone proximity and minimal room echo","Check audio levels and pacing across the full 2 minutes"]'::jsonb, 20, '[{"id":"cm72-1","type":"bullets","title":"Quick Home Recording Setup","items":["Record in a quiet room with soft curtains or carpets to reduce echo.","Place phone/mic 25–40cm away slightly below chin height.","Wait 2 silent seconds before speaking and 2 seconds after finishing before stopping recording."]}]'::jsonb, '[]'::jsonb, 'Clean audio clarity makes even modest home recordings effortless to review and evaluate.', '["Good audio matters more to listeners than 4K camera resolution","Leave 2 seconds of clean room silence at start and end"]'::jsonb, '[{"title":"NPR Training: Recording Clean Voice Audio","url":"https://training.npr.org/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('ef763b4b-cd5d-c7f3-6c90-bdfdcd38e13d'::uuid, '150dc5cb-6006-190d-a257-5f17784ef5bb'::uuid, 1, 'The Three-Pass Video Self-Review Technique', 'Watching yourself on video feels awkward at first—separating audio, body language, and structure keeps self-critique objective and kind.', '["Evaluate vocal pacing with eyes closed","Evaluate posture and gestures on mute","Verify structure and 2-minute timing"]'::jsonb, 25, '[{"id":"cm81-1","type":"steps","title":"Three-Pass Diagnostic Method","items":["Pass 1 (Audio only): Listen for filler words, monotone stretches, and rushed endings.","Pass 2 (Muted video): Check posture, distracting fidgeting, and camera/audience focus.","Pass 3 (Full playback): Verify the 15-second hook, 3 core pillars, and clear closing CTA landed within ~2 minutes."]}]'::jsonb, '[]'::jsonb, 'Objective three-pass review turns vague self-consciousness into targeted vocal and visual growth.', '["Notice what works well first before fixing habits","Fix one habit per rehearsal take rather than chasing perfection at once"]'::jsonb, '[{"title":"Toastmasters: Effective Evaluation","url":"https://www.toastmasters.org/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true),
  ('70c41de5-b402-56d6-b3f7-159e5554d1fd'::uuid, '150dc5cb-6006-190d-a257-5f17784ef5bb'::uuid, 2, 'Giving & Receiving Constructive Speaking Feedback', 'Observation-based feedback ("At 0:45 your pause made the statistic pop") helps speakers far more than vague praise.', '["Give specific timestamped observations","Synthesise feedback into a repeatable personal rehearsal checklist"]'::jsonb, 20, '[{"id":"cm82-1","type":"paragraph","text":"Every polished speaker maintains a short personal pre-flight card: 3 strengths to trust and 1 focus habit for the current talk."}]'::jsonb, '[]'::jsonb, 'Deliberate reflection after every talk compounds speaking skill across your career.', '["Anchor feedback to specific moments and impact on listeners","Archive outlines and reflections so progress stays measurable"]'::jsonb, '[{"title":"HBR: Feedback That Actually Helps","url":"https://hbr.org/"}]'::jsonb, 'Read the instructional guide, verify any inline knowledge checks, and mark this lesson complete.', 'published', true)
