    ('57cb848d-3a5b-1800-a34a-f18967b6e01a'::uuid, 'MindTools: Communication Skills Overview', 'https://www.mindtools.com/page8.html', 'article', 1),
    ('e891d817-821a-f7fc-57b9-f1ada764ad1e'::uuid, 'HBR: How to Become a Better Listener', 'https://hbr.org/', 'article', 1),
    ('7d4e0259-d96a-2787-9e55-776bd02d49c8'::uuid, 'Toastmasters: Vocal Variety Guide', 'https://www.toastmasters.org/resources/public-speaking-tips', 'article', 1),
    ('b85d577f-ea92-5458-f063-7170cce06ad2'::uuid, 'PlainLanguage.gov Principles', 'https://www.plainlanguage.gov/', 'article', 1),
    ('487d77c8-2667-ee02-8e57-e7b8ba429d40'::uuid, 'TED: Speaking Body Language Tips', 'https://ideas.ted.com/', 'article', 1),
    ('19df7ab2-6058-d206-c209-d37f9422456d'::uuid, 'Stanford Virtual Human Interaction Lab', 'https://vhil.stanford.edu/', 'article', 1),
    ('0f60a6f3-ac76-9eb7-595d-bf03280cccdb'::uuid, 'Toastmasters: Know Your Audience', 'https://www.toastmasters.org/', 'article', 1),
    ('7c95b25a-5428-b443-0574-e8aa66e5f3a4'::uuid, 'Duarte: Audience Empathy Mapping', 'https://www.duarte.com/', 'article', 1),
    ('5c99309f-001e-7d50-0225-45cdd4053357'::uuid, 'TEDx Speaker Guide', 'https://www.ted.com/participate/organize-a-local-tedx-event/tedx-organizer-guide/speakers-program/prepare-your-speaker', 'article', 1),
    ('0f25d74a-07ad-21fc-8119-170bee6dfabd'::uuid, 'Carmine Gallo: Talk Like TED', 'https://www.carminegallo.com/', 'article', 1),
    ('87086aaa-7a96-4cbb-a0f2-ae804d03e69e'::uuid, 'Aristotle’s Rhetoric Overview', 'https://plato.stanford.edu/entries/aristotle-rhetoric/', 'article', 1),
    ('eba202b4-0370-f040-a704-fddf26776025'::uuid, 'HBR: Handling Tough Questions in Presentations', 'https://hbr.org/', 'article', 1),
    ('0c24496c-a51d-1c84-9698-0e2cbbbec8fa'::uuid, 'Toastmasters: Overcoming Nervousness', 'https://www.toastmasters.org/resources/public-speaking-tips', 'article', 1),
    ('392648b2-0ef1-013a-ccb1-52c13a1c9c74'::uuid, 'NPR Training: Recording Clean Voice Audio', 'https://training.npr.org/', 'article', 1),
    ('ef763b4b-cd5d-c7f3-6c90-bdfdcd38e13d'::uuid, 'Toastmasters: Effective Evaluation', 'https://www.toastmasters.org/', 'article', 1),
    ('70c41de5-b402-56d6-b3f7-159e5554d1fd'::uuid, 'HBR: Feedback That Actually Helps', 'https://hbr.org/', 'article', 1)
) as v(lesson_id, title, url, resource_type, position)
join public.lessons l on l.id = v.lesson_id
on conflict (lesson_id, url) do update set title = excluded.title, position = excluded.position;

-- 9. Practical Module Activities (32)
insert into public.activities (id, phase_id, position, title, description, instructions, expected_output, est_minutes, is_required, resources)
values
  ('16685950-0db0-224b-fdfd-358686131332'::uuid, '1452f148-671a-6af7-3d7d-91427b39afa1'::uuid, 1, 'Inspect and Map a Live Webpage Architecture', 'Open any public homepage in DevTools Elements and Network tabs. Document its landmark tags, stylesheet count, and largest layout shift culprit.', 'Inspect a site in DevTools (F12), identify <header>, <nav>, <main>, <footer>, and note 3 CSS custom properties or font rules.', 'A brief 5-line structural breakdown saved in your activity notes.', 25, true, '[]'::jsonb),
  ('846f7c5c-f69f-c0b2-25a3-a57a0eb82b82'::uuid, 'd038cf02-89ce-4d92-fa33-4a10e271793e'::uuid, 1, 'Write a Semantic 3-Section Business Homepage Skeleton', 'Draft pure HTML5 (no CSS yet) for a local service business with <header>, <nav>, hero <section>, services <article> cards, and <footer>.', 'Verify there is exactly one <h1>, no skipped heading levels, and meaningful alt text on every <img>.', 'Valid semantic HTML document outline verified without skipped heading levels.', 30, true, '[]'::jsonb),
  ('361b7cd4-98ef-f968-ea06-2667ec01e775'::uuid, '2d272456-d4a8-88d6-a92e-1eb58dcc0503'::uuid, 1, 'Build a Reusable Tokenised Stylesheet', 'Define :root variables for background, surface, primary text, accent colour, and spacing scale, then style a 2-card section using clean class selectors.', 'Verify WCAG AA contrast (>= 4.5:1) on body text and buttons.', 'CSS file using :root tokens and border-box sizing with zero !important overrides.', 30, true, '[]'::jsonb),
  ('d73a12fb-d9c0-bde0-3391-2aa3557d7ea7'::uuid, '1939f24b-98de-af0a-4beb-3217cfcdacba'::uuid, 1, 'Implement a Responsive Header + 3-Column Feature Grid', 'Create a responsive page layout that stacks cleanly at 375px, switches to 2 columns at 768px, and shows 3 equal-height cards at 1200px.', 'Test both 375px and 1440px viewports in DevTools and confirm zero horizontal scroll.', 'Flexbox navigation bar and CSS Grid card grid with zero overflow.', 35, true, '[]'::jsonb),
  ('8508b5d0-f72d-1092-28f8-750b845597ab'::uuid, '420b4329-9c17-0c00-c0fd-c951a1cc859a'::uuid, 1, 'Write a Service Catalogue Filter & Price Calculator', 'Given an array of 6 service packages, write pure JS functions to filter by category, format prices, and compute total selected quote cost.', 'Use const, .filter(), .map(), and .reduce() without mutating the source array.', 'Three pure JS helper functions tested with sample objects.', 30, true, '[]'::jsonb),
  ('1a7f5c3b-ff21-c5a5-c852-123ab635cfee'::uuid, 'b5b3aedb-70a3-ad9b-f3cc-53d5e98b49e8'::uuid, 1, 'Build an Interactive FAQ Accordion & Category Filter', 'Wire vanilla JS click handlers that toggle aria-expanded on FAQ items and filter visible service cards dynamically.', 'Update both the visual state and aria-expanded attribute when toggling an accordion row.', 'Interactive FAQ accordion and category filter working with keyboard and mouse.', 30, true, '[]'::jsonb),
  ('531a06e5-0128-b999-b11e-1dfcf550a45d'::uuid, 'fd887f97-0b99-8407-d9b7-28bc23d4f741'::uuid, 1, 'Create a Validated Business Inquiry Form', 'Build a contact/quote form checking name length, valid email format, service selection, and 20+ character message with inline field errors.', 'Prevent default submission on invalid input, focus the first invalid field, and show a confirmation banner on success.', 'Accessible contact form with inline errors and live submission confirmation.', 30, true, '[]'::jsonb),
  ('67630f50-f116-a2d4-68a0-dd402f9e6969'::uuid, 'd4e2b59d-c916-e976-6b79-4d636f308e48'::uuid, 1, 'Run a Complete Pre-Launch Lighthouse & Keyboard Audit', 'Test your multi-section business website using keyboard Tab navigation, mobile emulation, and DevTools Lighthouse prior to deployment.', 'Record your scores and list 2 concrete improvements made before final publish.', 'Verified keyboard focus flow, compressed images, and clean deployment URL.', 30, true, '[]'::jsonb),
  ('e782926d-f5e6-3387-6196-0cb09bf218a5'::uuid, '31078ffa-e680-0e73-5784-4bc0204f658f'::uuid, 1, 'Visual Brief Audit & Tear-Sheet Critique', 'Select one printed flyer or event poster you encounter this week and identify its primary message, secondary callout, and target audience.', 'Write 3 bullets: what grabs attention first, what action is requested, and one visual improvement.', 'Structured 3-point design critique saved in notes.', 25, true, '[]'::jsonb),
  ('a2415faa-746f-0294-0cfa-a84184989717'::uuid, '5cb69c74-cde2-63c7-9eff-99d475b442fe'::uuid, 1, 'Negative Space & Scale Contrast Study', 'Draft two versions of an event announcement card: one cluttered, and one refined using generous whitespace and a 3:1 headline-to-body scale ratio.', 'Leave at least 30% open negative space around your primary focal area.', 'Short comparison note describing how whitespace changed readability.', 30, true, '[]'::jsonb),
  ('35cd1db0-f22f-4e53-1033-b1ac60f2e9b8'::uuid, '72747bc7-f08d-7150-456f-63ed8621c540'::uuid, 1, 'Curate a 3-Swatch 60-30-10 Palette with Contrast Check', 'Select one dominant neutral background (60%), one structural surface/text tone (30%), and one focal accent (10%), verifying >= 4.5:1 text contrast.', 'Record hex values plus planned CMYK print adjustments.', '3-swatch palette table with verified foreground/background contrast ratios.', 25, true, '[]'::jsonb),
  ('c34f47f8-d545-bc0d-309a-ba7966465546'::uuid, 'a536bd2d-4629-4ffd-e289-1fb96a3701db'::uuid, 1, 'Design a 3-Level Typographic Specimen Sheet', 'Combine one expressive Display heading typeface with a neutral readable Body font across H1, Subhead, Body, and Metadata sizes.', 'Keep line lengths between 45–75 characters and avoid centred multi-line body paragraphs.', 'Documented font pairing with exact sizes, weights, and line heights.', 30, true, '[]'::jsonb),
  ('975098ec-fc0e-a52e-2b15-bffc2aee3760'::uuid, '649489f2-ad65-af24-188f-a3aa20b13aa2'::uuid, 1, 'Rebuild a Cluttered Flyer Onto a 6-Column Grid', 'Plan a 6-column or 12-column grid with uniform outer margins and align every headline, image edge, and venue detail block onto grid lines.', 'Verify zero stray floating elements sit off-grid without intentional reason.', 'Grid specification and alignment notes.', 30, true, '[]'::jsonb),
  ('fe9f726b-ee83-f2f1-4fc4-27fe71faf1c9'::uuid, '01eaf2c3-097d-3b9f-0c1d-97df91122f34'::uuid, 1, 'Author a 1-Page Fictional Business Brand Sheet', 'Invent a fictional business (bakery, bike repair studio, bookstore, or design workshop) with name, tagline, 3 tone adjectives, 2 fonts, and 3 colours.', 'Use this exact fictional business later for your final promotional flyer project.', 'Brand sheet outlining audience, tone, fonts, and hex/CMYK palette.', 30, true, '[]'::jsonb),
  ('584669c9-e628-f194-5023-3a2c8d87e5db'::uuid, 'd1af902a-0525-a077-325b-48ae16152342'::uuid, 1, 'Build a Layered Digital Template in Figma, Canva, or Affinity', 'Set up an A5 or Letter flyer artboard with 3mm bleed guides, named layer groups (Background, Visual, Copy, Footer), and reusable colour/text styles.', 'Verify all text uses shared styles and photos sit inside clean masked frames.', 'Confirmation of structured layer hierarchy and bleed setup.', 30, true, '[]'::jsonb),
  ('e5133ac1-c0e6-4dc1-f713-9f316d5e5273'::uuid, '70274843-cdb0-65d3-eec9-1e9773769b27'::uuid, 1, 'Pre-Press Flight Check & Export Verification', 'Inspect your finished promotional flyer at 100% zoom for spelling, alignment, 3mm bleed extension, and clean PDF/PNG export.', 'Check spelling of all dates/addresses twice and confirm zero clipped edge text.', 'Verified print-ready PDF and crisp PNG export ready for capstone submission.', 25, true, '[]'::jsonb),
  ('c2b6d708-492c-a268-158e-ab2b848299ff'::uuid, '6ee2ae2b-51e5-30da-6985-df81dcd26c65'::uuid, 1, 'Map a Full-Funnel Channel Matrix', 'Pick a real or fictional product and document one Owned, one Earned, and one Paid touchpoint supporting each funnel stage.', 'Identify the primary conversion event (lead form, booking, or checkout) before choosing channels.', '4-stage funnel table mapping channel + goal + CTA.', 25, true, '[]'::jsonb),
  ('55761b8f-b1fc-3202-c73a-80266cc85349'::uuid, '4fbbb134-2d0a-2a8f-0cd3-2e5d2da2f1ac'::uuid, 1, 'Voice-of-Customer Pain & Objection Sheet', 'Read 10 real public customer reviews in your target niche and extract 5 exact phrases describing frustrations, desired outcomes, and doubts.', 'Record verbatim customer wording rather than marketing buzzwords.', '5 verbatim customer pain/desire insights ready for copywriting.', 30, true, '[]'::jsonb),
  ('d8799a0c-df58-7093-ec77-bfe649c455e0'::uuid, 'eef6d687-2e34-9aa3-e674-dc02fe223505'::uuid, 1, 'Design a 3-Pillar Content Matrix & 1-to-4 Repurposing Plan', 'Define 3 educational content pillars for your campaign brand and outline how one flagship article turns into 4 platform-native posts.', 'Include headline, target takeaway, and soft CTA for each asset.', 'Content pillar plan with 4 derivative formats.', 25, true, '[]'::jsonb),
  ('195eb8ed-d92b-6d6f-060c-870e5605778a'::uuid, '8927aa09-f63d-ace2-96c4-a60f0deee13b'::uuid, 1, 'Draft 4 Platform-Native Social Posts for One Offer', 'Write hooks, body text, visual direction, and engagement prompts for 4 posts tailored to 2 chosen channels.', 'Make sure the opening line earns attention without clickbait.', '4 formatted social post drafts with visual briefs.', 30, true, '[]'::jsonb),
  ('232847dd-1caa-0a18-ae89-7cef2da79922'::uuid, '5f2f372b-dd2c-ac45-c4dc-55da52b3fdc4'::uuid, 1, 'Rewrite 3 Vague Headlines Using Feature -> Benefit + PAS', 'Take 3 generic product statements and craft specific benefit-led headlines plus one short PAS email body.', 'Replace vague adjectives ("best", "revolutionary") with concrete timeframes, numbers, or outcomes.', '3 crisp headlines + 1 PAS email draft.', 30, true, '[]'::jsonb),
  ('64051bd2-3345-accd-c7c7-a1a23bfb8d40'::uuid, '114e11c2-a54b-c081-a03a-cb36e2526054'::uuid, 1, 'Draft a Campaign Brief & UTM Naming Sheet', 'Define campaign objective, KPI target, audience, budget split, and standardised utm_source/utm_medium/utm_campaign tags.', 'Keep all UTM values lowercase with hyphens or underscores consistently.', '1-page launch brief + 4 tagged campaign URLs.', 25, true, '[]'::jsonb),
  ('26b54d3d-133c-9c67-706c-76fd6483e1b4'::uuid, '9f52fbd6-9d99-0385-cee9-e5387e33ec33'::uuid, 1, 'Diagnose a Mock Campaign Funnel Table', 'Calculate CTR, Landing Page Conversion Rate, and CPA for two sample campaigns and decide which bottleneck to fix first.', 'Campaign A: 10,000 impressions, 300 clicks, 3 leads ($300 spend). Campaign B: 10,000 impressions, 70 clicks, 14 leads ($300 spend). Explain what each pair reveals.', 'Calculated metrics + diagnostic action for both campaigns.', 30, true, '[]'::jsonb),
  ('101ab3e3-1995-a28c-9764-bd85813c5e44'::uuid, '9fb320ae-27f3-b05e-789b-a184bc9e631a'::uuid, 1, 'Write 2 Structured A/B Test Hypotheses', 'Write two experiment cards specifying variable changed, control vs variant, primary success metric, and minimum sample threshold.', 'Test only one major variable per experiment (e.g., headline angle OR hero visual, not five things at once).', '2 clean A/B experiment plans.', 25, true, '[]'::jsonb),
  ('1a8d9960-8693-9223-f6a9-8eaf77125ba8'::uuid, 'a37791dc-3d3a-9c1a-2ea0-d13fe9246459'::uuid, 1, 'Diagnose a Miscommunication Episode', 'Recall a recent workplace or personal misunderstanding and identify which barrier (semantic ambiguity, assumption, timing, or channel mismatch) caused it.', 'Write a 3-sentence rewrite showing how upfront clarity would have prevented it.', 'Identified barrier + clearer opening phrasing.', 20, true, '[]'::jsonb),
  ('d7acecfe-a17e-c6fc-3f19-904990ea15fc'::uuid, 'de26ab8c-a851-617c-5422-c354be6c14a7'::uuid, 1, '60-Second Pause & Pacing Drill', 'Read a 120-word explanation aloud twice: first rushed, then pausing deliberately at every period and lowering speed slightly on the main point.', 'Record a quick voice memo on your phone to hear where rushing or filler words sneak in.', 'Self-notes identifying 2 words or phrases to slow down.', 20, true, '[]'::jsonb),
  ('350d42be-b03f-ee16-6d80-e65f7ec9ad58'::uuid, 'ee983d8d-2805-6161-6ecf-c65338897282'::uuid, 1, 'Camera & Posture Framing Check', 'Set up your webcam or phone at eye level, stand or sit tall with visible upper-body gesture space, and record a 20-second silent check.', 'Verify eye-level lens height, balanced shoulder posture, and calm neutral background.', 'Framing checklist confirmation in activity notes.', 20, true, '[]'::jsonb),
  ('4f9f06b1-4435-5ead-9d55-6b66207f1c95'::uuid, '667f0407-11a9-0e7c-1d61-dc368efd2f01'::uuid, 1, 'Write Two Openers for One Topic', 'Take a single 2-minute talk idea and write one opening hook tailored to busy executives and another tailored to frontline peers.', 'Focus on what each group cares about most in the first 20 seconds.', '2 contrasting 40-word opening hooks.', 25, true, '[]'::jsonb),
  ('b93af8d2-a352-e8e0-0513-2b9ddd38da64'::uuid, '0094ebe1-50a1-eb7f-a60d-a31d7cf80bbb'::uuid, 1, 'Build Your Two-Minute Presentation Outline', 'Draft a crisp 2-minute talk outline (~260–300 words) featuring a 15-second hook, 3 core pillars with evidence, and a 20-second call-to-action close.', 'Use bulleted cue keywords rather than a dense wall of full-sentence reading text.', 'Structured 2-minute speech outline ready for rehearsal.', 30, true, '[]'::jsonb),
  ('d356ac2c-2cdf-9f28-5145-b166103502e8'::uuid, '093c960b-d447-0ba6-c2ef-5cf102b861cb'::uuid, 1, 'Build an Ethos–Pathos–Logos & Objection Response Card', 'For your 2-minute talk topic, document 1 credibility signal, 1 human story/example, 1 data proof point, and 1 calm response to a likely objection.', 'Ensure every factual claim stays completely honest and verifiable.', 'Persuasive balance sheet + 1 Acknowledge-Bridge-Evidence answer.', 25, true, '[]'::jsonb),
  ('2401fae2-9276-2e64-c8fb-261e5892a9d1'::uuid, '5b22e202-5186-acaa-dd56-23c790c35cf6'::uuid, 1, 'Timed Dress Rehearsal with Keyword Cue Cards', 'Deliver your 2-minute presentation twice aloud against a timer using only 3–4 cue-card bullet keywords per section (no word-for-word reading).', 'Target 1:50 to 2:10 duration with smooth transitions.', 'Recorded rehearsal timings and 1 adjustment made between take 1 and take 2.', 30, true, '[]'::jsonb),
  ('81bf9bc3-9f23-422c-f2b2-7fb7dd237d51'::uuid, '150dc5cb-6006-190d-a257-5f17784ef5bb'::uuid, 1, 'Three-Pass Self-Critique on Your Practice Recording', 'Watch your practice take three times: (1) audio only (eyes closed), (2) muted video only, and (3) full playback with timing check.', 'Write 2 concrete strengths and 2 targeted improvements for your final recording.', 'Completed 3-pass reflection notes ready to refine your final submission.', 25, true, '[]'::jsonb)
on conflict (phase_id, position) do update set
  title = excluded.title,
  description = excluded.description,
  instructions = excluded.instructions,
  expected_output = excluded.expected_output,
  est_minutes = excluded.est_minutes,
  is_required = excluded.is_required,
  resources = excluded.resources;

-- 10. Assessments / Quizzes (9)
insert into public.quizzes (id, skill_id, course_id, phase_id, quiz_type, title, description, pass_percent, time_limit_minutes, max_attempts, shuffle_questions, requires_manual_review)
select v.id::uuid, sk.id, co.id, ph.id, v.quiz_type, v.title, v.description, v.pass_percent, v.time_limit_minutes, v.max_attempts, v.shuffle_questions, v.requires_manual_review
from (
  values
    ('4e621cb8-9470-ae38-b100-2e6ca709cf30', 'frontend-development', 'frontend-development-foundations', '1939f24b-98de-af0a-4beb-3217cfcdacba'::uuid, 'phase', 'HTML, CSS & Responsive Layout Assessment', 'Verify core understanding of browser rendering, semantic HTML5, specificity, Box Model, Flexbox, and CSS Grid.', 70, 15, 5, false, false),
    ('04043053-6f15-4ad8-43c9-d8f3c7ebb11b', 'frontend-development', 'frontend-development-foundations', 'fd887f97-0b99-8407-d9b7-28bc23d4f741'::uuid, 'phase', 'JavaScript, DOM & Forms Assessment', 'Assess pure JavaScript transformations, safe DOM manipulation, event delegation, and accessible form validation.', 70, 15, 5, false, false),
    ('3acef753-23e2-e1c5-7dcb-f7a7c2d5a3ef', 'frontend-development', 'frontend-development-foundations', 'd4e2b59d-c916-e976-6b79-4d636f308e48'::uuid, 'course_exam', 'Frontend Development Foundations Course Exam', 'Comprehensive exam covering web architecture, HTML semantics, responsive CSS, JS logic, validation, and deployment.', 75, 25, 4, false, false),
    ('dfd4ac72-cc59-9346-c0a1-db639531c8c4', 'graphic-design', 'graphic-design-foundations', 'a536bd2d-4629-4ffd-e289-1fb96a3701db'::uuid, 'phase', 'Design Elements, Colour & Typography Assessment', 'Test understanding of whitespace, 60-30-10 colour harmony, RGB vs CMYK, and typographic hierarchy.', 70, 15, 5, false, false),
    ('14adf1a2-af0c-e71c-0e9f-0efcfb3a3b15', 'graphic-design', 'graphic-design-foundations', '70274843-cdb0-65d3-eec9-1e9773769b27'::uuid, 'course_exam', 'Graphic Design Foundations Course Exam', 'Comprehensive exam covering layout grids, brand consistency, vector vs raster formats, and print production.', 75, 20, 4, false, false),
    ('0c1db88b-7cc6-9dd4-5292-d5b875e21b94', 'digital-marketing-fundamentals', 'digital-marketing-foundations', '8927aa09-f63d-ace2-96c4-a60f0deee13b'::uuid, 'phase', 'Strategy, Research & Content Foundations Assessment', 'Check mastery of media categories, audience triggers, content pillars, and social platform selection.', 70, 15, 5, false, false),
    ('c0cdb4cc-ff7b-e9ae-8bec-4a3225a42bfc', 'digital-marketing-fundamentals', 'digital-marketing-foundations', '9fb320ae-27f3-b05e-789b-a184bc9e631a'::uuid, 'course_exam', 'Digital Marketing Foundations Course Exam', 'Comprehensive exam covering copywriting frameworks, campaign planning, UTMs, funnel metrics, and A/B testing.', 75, 20, 4, false, false),
    ('977da3aa-3615-85d0-c33a-3a2e09021adc', 'public-speaking', 'communication-and-public-speaking', '667f0407-11a9-0e7c-1d61-dc368efd2f01'::uuid, 'phase', 'Communication, Delivery & Audience Assessment', 'Assess active listening, vocal pacing, non-verbal framing, and audience analysis principles.', 70, 15, 5, false, false),
    ('ba985c5c-53ee-5cf3-d4ce-22ac6695f7a4', 'public-speaking', 'communication-and-public-speaking', '150dc5cb-6006-190d-a257-5f17784ef5bb'::uuid, 'course_exam', 'Communication & Public Speaking Course Exam', 'Comprehensive exam covering presentation structure, persuasive framing, timed rehearsal, and three-pass self-review.', 75, 20, 4, false, false)
) as v(id, skill_slug, course_slug, phase_uuid, quiz_type, title, description, pass_percent, time_limit_minutes, max_attempts, shuffle_questions, requires_manual_review)
join public.skills sk on sk.slug = v.skill_slug
left join public.courses co on co.slug = v.course_slug
left join public.phases ph on ph.id = v.phase_uuid
on conflict (id) do update set
  skill_id = excluded.skill_id,
  course_id = excluded.course_id,
  phase_id = excluded.phase_id,
  quiz_type = excluded.quiz_type,
  title = excluded.title,
  description = excluded.description,
  pass_percent = excluded.pass_percent,
  time_limit_minutes = excluded.time_limit_minutes,
  max_attempts = excluded.max_attempts,
  shuffle_questions = excluded.shuffle_questions,
  requires_manual_review = excluded.requires_manual_review;

-- 11. Assessment Questions (29)
insert into public.questions (id, quiz_id, position, question_type, difficulty, marks, prompt, context_text, options, correct_index, answer_config, explanation)
values
  ('96043600-d3b2-7eee-dd7f-09ad5f649b2e'::uuid, '4e621cb8-9470-ae38-b100-2e6ca709cf30'::uuid, 1, 'multiple_choice', 'medium', 2, 'Which CSS property ensures padding and borders are included inside an element’s declared width?', '', '["display: inline-block","box-sizing: border-box","overflow: hidden","position: relative"]'::jsonb, 1, '{}'::jsonb, 'box-sizing: border-box keeps width/height inclusive of padding and border, preventing unexpected overflow.'),
  ('26439e04-efc5-d55a-64b7-ca22e601d960'::uuid, '4e621cb8-9470-ae38-b100-2e6ca709cf30'::uuid, 2, 'multiple_choice', 'medium', 2, 'What is the primary benefit of semantic HTML landmarks like <main> and <nav>?', '', '["Automatic dark-mode styling","Keyboard and screen-reader navigation structure","Faster JavaScript execution"]'::jsonb, 1, '{}'::jsonb, 'Assistive technologies expose semantic landmarks so users can jump straight to navigation or main content.'),
  ('0f57a7a0-66e9-99b1-1071-112f364789b9'::uuid, '4e621cb8-9470-ae38-b100-2e6ca709cf30'::uuid, 3, 'multiple_choice', 'medium', 2, 'When should you prefer CSS Grid over Flexbox?', '', '["Aligning items strictly along a single horizontal row","Designing a two-dimensional layout with both columns and rows","Animating hover colours"]'::jsonb, 1, '{}'::jsonb, 'CSS Grid excels at 2D column-and-row alignment; Flexbox excels at 1D distribution.'),
  ('547dfe56-d70e-a00a-4ce9-fc54d82b813d'::uuid, '4e621cb8-9470-ae38-b100-2e6ca709cf30'::uuid, 4, 'multiple_choice', 'medium', 2, 'Why should an icon that sits next to already-descriptive button text have alt=""?', '', '["To skip redundant screen-reader announcements","To hide the icon visually","To reduce file size"]'::jsonb, 0, '{}'::jsonb, 'Empty alt="" marks an image as decorative so assistive technology does not read redundant noise.'),
  ('1c204c28-7dbd-4b8e-0ed2-704cf21d1402'::uuid, '04043053-6f15-4ad8-43c9-d8f3c7ebb11b'::uuid, 1, 'multiple_choice', 'medium', 2, 'Which method avoids Cross-Site Scripting (XSS) when inserting user-submitted text into a card?', '', '["element.innerHTML = userText","element.textContent = userText","document.write(userText)"]'::jsonb, 1, '{}'::jsonb, 'textContent treats strings strictly as literal text and never parses embedded HTML or <script> tags.'),
  ('227d02ef-2dbc-c64d-9dcb-221448e04b9b'::uuid, '04043053-6f15-4ad8-43c9-d8f3c7ebb11b'::uuid, 2, 'multiple_choice', 'medium', 2, 'How do you handle clicks on dynamically rendered list buttons without binding a listener to each button?', '', '["Inline onclick strings","Event delegation on the parent container using e.target.closest()","setInterval polling"]'::jsonb, 1, '{}'::jsonb, 'Delegated listeners on a stable parent inspect e.target.closest(...) and survive re-renders cleanly.'),
  ('42f1f983-a743-39ab-db82-3a20597912c3'::uuid, '04043053-6f15-4ad8-43c9-d8f3c7ebb11b'::uuid, 3, 'multiple_choice', 'medium', 2, 'In an accessible HTML form, how should a custom validation error be communicated?', '', '["Turn the border red with no text","Show clear inline text next to the field and pair every input with a <label>","Use a browser alert() dialog on every keystroke"]'::jsonb, 1, '{}'::jsonb, 'Inline error messages paired with labelled fields satisfy WCAG AA non-colour-only error communication.'),
  ('bd9b825c-255b-0eac-210c-ff40c720c0cf'::uuid, '3acef753-23e2-e1c5-7dcb-f7a7c2d5a3ef'::uuid, 1, 'multiple_choice', 'medium', 2, 'Which meta tag is required for mobile browsers to honour responsive CSS media queries cleanly?', '', '["<meta name=\"robots\" content=\"index\">","<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">","<meta charset=\"ASCII\">"]'::jsonb, 1, '{}'::jsonb, 'Without width=device-width, mobile browsers zoom out to a simulated ~980px desktop viewport.'),
  ('9d9be248-2ae7-a1c8-74b0-65797e0f9a30'::uuid, '3acef753-23e2-e1c5-7dcb-f7a7c2d5a3ef'::uuid, 2, 'multiple_choice', 'medium', 2, 'What happens if a CSS file uses root-absolute /styles/main.css when deployed under https://user.github.io/site-name/?', '', '["It resolves relative to the domain root and breaks with a 404","It loads twice as fast","GitHub automatically rewrites it"]'::jsonb, 0, '{}'::jsonb, 'Relative paths (./styles/main.css) work consistently across root domains and project sub-paths.'),
  ('6b6bbbf2-6b7f-004f-3f9b-1bdf9cdd2a83'::uuid, '3acef753-23e2-e1c5-7dcb-f7a7c2d5a3ef'::uuid, 3, 'multiple_choice', 'medium', 2, 'Which JavaScript expression creates a sorted copy of an array without mutating the original?', '', '["items.sort()","items.slice().sort((a, b) => a.price - b.price)","items.filter(Boolean)"]'::jsonb, 1, '{}'::jsonb, '.slice() creates a shallow copy first because Array.prototype.sort() mutates arrays in place.'),
  ('ef99b9a9-5ccf-8afc-e27a-e702be140165'::uuid, '3acef753-23e2-e1c5-7dcb-f7a7c2d5a3ef'::uuid, 4, 'multiple_choice', 'medium', 2, 'Does passing this exam alone award Verified practical competence?', '', '["Yes, 100%","No—practical competence requires building and earning approval on the responsive business website project"]'::jsonb, 1, '{}'::jsonb, 'Quizzes measure conceptual understanding; practical competence requires reviewed implementation evidence.'),
  ('b244af0e-6de3-d343-893c-74aec57045fd'::uuid, 'dfd4ac72-cc59-9346-c0a1-db639531c8c4'::uuid, 1, 'multiple_choice', 'medium', 2, 'Under the 60-30-10 colour system, what does the 60% allocation typically represent?', '', '["Bright CTA buttons","Calm dominant neutral canvas","Small metadata labels"]'::jsonb, 1, '{}'::jsonb, '60% calm neutral backdrop lets the 30% structural tones and 10% focal accent guide attention clearly.'),
  ('8c01cca5-3aba-b0c6-d089-fcaf56e8ab0f'::uuid, 'dfd4ac72-cc59-9346-c0a1-db639531c8c4'::uuid, 2, 'multiple_choice', 'medium', 2, 'Which alignment is generally easiest to scan for multi-line body paragraphs?', '', '["Left-aligned","Centred on every line","Widely justified with uneven gaps"]'::jsonb, 0, '{}'::jsonb, 'Left alignment gives the reader’s eye a consistent starting edge on every line.'),
  ('e42a5726-f5cd-df32-6263-635d184d19f0'::uuid, 'dfd4ac72-cc59-9346-c0a1-db639531c8c4'::uuid, 3, 'multiple_choice', 'medium', 2, 'Why should promotional flyers convert or verify colours for CMYK before commercial offset printing?', '', '["Ink absorbs light differently than glowing monitor pixels","Monitors cannot display black ink","CMYK increases font count"]'::jsonb, 0, '{}'::jsonb, 'Bright additive RGB hues (especially neon greens/blues) shift duller in subtractive CMYK ink.'),
  ('06b36170-2f10-45a7-c328-8a0c30e4b424'::uuid, '14adf1a2-af0c-e71c-0e9f-0efcfb3a3b15'::uuid, 1, 'multiple_choice', 'medium', 2, 'Which file format stays razor-sharp at both business-card size and billboard size for a brand logo?', '', '["Low-res 72 PPI JPEG","Vector format (SVG / PDF vector)","Screenshot PNG"]'::jsonb, 1, '{}'::jsonb, 'Vector paths scale mathematically to any dimension without pixelation.'),
  ('f918c15f-a9c8-47c5-66a1-65a27678abd9'::uuid, '14adf1a2-af0c-e71c-0e9f-0efcfb3a3b15'::uuid, 2, 'multiple_choice', 'medium', 2, 'What is the purpose of adding a 3mm bleed around a print flyer layout?', '', '["Preventing thin white slivers along edges after trimming","Adding extra text lines","Compressing file size"]'::jsonb, 0, '{}'::jsonb, 'Background visuals extend 3mm past the trim line to cover mechanical cutting tolerance.'),
  ('43fce821-76a1-bea6-2b67-e80e61cddf40'::uuid, '14adf1a2-af0c-e71c-0e9f-0efcfb3a3b15'::uuid, 3, 'multiple_choice', 'medium', 2, 'What does "Three-Second Read" measure on a promotional flyer?', '', '["Printer warm-up time","How quickly a viewer grasps what is offered, who it is for, and the action to take","Number of decorative icons"]'::jsonb, 1, '{}'::jsonb, 'Strong hierarchy communicates the core offer and CTA within three seconds.'),
  ('f65ffe04-b711-8a9d-bd96-b66c38dd59af'::uuid, '0c1db88b-7cc6-9dd4-5292-d5b875e21b94'::uuid, 1, 'multiple_choice', 'medium', 2, 'What is "Message-Match" in digital marketing?', '', '["Using identical hashtags on every platform","Alignment between the promise in an ad/post and the headline on the landing page","Matching ad font colour to browser chrome"]'::jsonb, 1, '{}'::jsonb, 'Visitors stay when the landing page immediately reinforces the exact promise they clicked.'),
  ('bd73688d-8ed3-4a2b-fa26-10aa3c0d6fca'::uuid, '0c1db88b-7cc6-9dd4-5292-d5b875e21b94'::uuid, 2, 'multiple_choice', 'medium', 2, 'Which research input yields the strongest ad and landing-page hooks?', '', '["Guessing trendy buzzwords","Verbatim customer frustrations and desired outcomes from reviews/interviews","Copying competitor mission statements"]'::jsonb, 1, '{}'::jsonb, 'Real customer language mirrors how target buyers think about their problems.'),
  ('ffa252d4-255e-47f9-9855-75b5cad9e55f'::uuid, '0c1db88b-7cc6-9dd4-5292-d5b875e21b94'::uuid, 3, 'multiple_choice', 'medium', 2, 'What does 1-to-4 content repurposing accomplish?', '', '["Transforms one well-researched flagship piece into native formats across channels","Spams identical screenshots hourly","Replaces analytics tracking"]'::jsonb, 0, '{}'::jsonb, 'Adapting one core idea natively saves time while respecting each channel’s format.'),
  ('52ec55a5-0f70-8e61-84d0-12c26f984b37'::uuid, 'c0cdb4cc-ff7b-e9ae-8bec-4a3225a42bfc'::uuid, 1, 'multiple_choice', 'medium', 2, 'An ad achieves a strong 3.4% CTR, but landing page conversion rate is 0.2%. Where should you investigate first?', '', '["Landing page load speed, clarity, and message-match","Making the ad thumbnail brighter","Changing the UTM campaign name"]'::jsonb, 0, '{}'::jsonb, 'High CTR proves the ad earns clicks; low landing CVR points straight to post-click friction or mismatch.'),
  ('00a1a51f-9f93-2d12-3480-cf10236d36b8'::uuid, 'c0cdb4cc-ff7b-e9ae-8bec-4a3225a42bfc'::uuid, 2, 'multiple_choice', 'medium', 2, 'Why should UTM tags never be added to internal navigation links inside your own website?', '', '["They overwrite the visitor’s original acquisition source in analytics","They slow down CSS loading","Browsers block ? characters internally"]'::jsonb, 0, '{}'::jsonb, 'Internal UTMs start a new session and erase true external attribution data.'),
  ('b0008ead-ba14-2c6c-ba25-e14bdb7dc74c'::uuid, 'c0cdb4cc-ff7b-e9ae-8bec-4a3225a42bfc'::uuid, 3, 'multiple_choice', 'medium', 2, 'In an A/B test, why do disciplined marketers alter only one primary variable per experiment?', '', '["To run tests faster with zero analytics","So performance differences can be cleanly attributed to that specific change","Because landing pages allow one button"]'::jsonb, 1, '{}'::jsonb, 'Changing multiple unrelated pieces simultaneously muddies cause-and-effect.'),
  ('675c0c50-41b8-79d9-09a5-a5029eefd2e9'::uuid, '977da3aa-3615-85d0-c33a-3a2e09021adc'::uuid, 1, 'multiple_choice', 'medium', 2, 'What is the most effective replacement for filler words ("um", "uh", "like") during a talk?', '', '["Speaking twice as fast","A calm 1-second silent pause","Reading a script word-for-word"]'::jsonb, 1, '{}'::jsonb, 'A brief silent pause sounds composed to listeners and helps you collect your next phrase cleanly.'),
  ('a6022c81-19b9-1eba-7d32-850e812f173c'::uuid, '977da3aa-3615-85d0-c33a-3a2e09021adc'::uuid, 2, 'multiple_choice', 'medium', 2, 'During a remote video presentation, where should you look while delivering your key opening hook and CTA?', '', '["Down at your notes","Directly at the camera lens","At your own thumbnail preview"]'::jsonb, 1, '{}'::jsonb, 'Looking directly at the lens simulates natural eye contact for remote listeners.'),
  ('84fadbcf-92bc-f75d-992e-72018ee4c137'::uuid, '977da3aa-3615-85d0-c33a-3a2e09021adc'::uuid, 3, 'multiple_choice', 'medium', 2, 'What does active listening require before you offer your solution?', '', '["Preparing your rebuttal while the other person talks","Paraphrasing and confirming you understood their core constraint","Changing the topic quickly"]'::jsonb, 1, '{}'::jsonb, 'Confirming understanding prevents wasted solutions and builds immediate trust.'),
  ('529923c3-4fb8-ac88-4b95-54526ee80157'::uuid, 'ba985c5c-53ee-5cf3-d4ce-22ac6695f7a4'::uuid, 1, 'multiple_choice', 'medium', 2, 'Why are keyword cue cards preferred over a dense word-for-word manuscript during rehearsal?', '', '["They preserve natural conversational pacing and prevent freezing if one word slips","They are heavier to hold","They hide your outline"]'::jsonb, 0, '{}'::jsonb, 'Keyword anchors let you adapt naturally to your room without sounding recited.'),
  ('a868bd28-6299-1df2-c99b-5edbc42708bc'::uuid, 'ba985c5c-53ee-5cf3-d4ce-22ac6695f7a4'::uuid, 2, 'multiple_choice', 'medium', 2, 'In the Ethos–Pathos–Logos model, what does Logos contribute?', '', '["Speaker attire","Clear logical reasoning and verifiable evidence","Hand gestures"]'::jsonb, 1, '{}'::jsonb, 'Logos grounds persuasion in logical argument and real evidence.'),
  ('10939df1-45a6-434d-16f2-5199d6eba0fb'::uuid, 'ba985c5c-53ee-5cf3-d4ce-22ac6695f7a4'::uuid, 3, 'multiple_choice', 'medium', 2, 'What is the purpose of reviewing a practice video once with the sound muted?', '', '["To isolate posture, camera framing, and distracting body movement objectively","To count filler words","To verify microphone volume"]'::jsonb, 0, '{}'::jsonb, 'Watching on mute spotlights visual habits without distraction from spoken content.')
on conflict (id) do update set
  quiz_id = excluded.quiz_id,
  position = excluded.position,
  question_type = excluded.question_type,
  difficulty = excluded.difficulty,
  marks = excluded.marks,
  prompt = excluded.prompt,
  context_text = excluded.context_text,
  options = excluded.options,
  correct_index = excluded.correct_index,
  answer_config = excluded.answer_config,
  explanation = excluded.explanation;

-- 12. Capstone Challenges (4)
insert into public.challenges (id, skill_id, course_id, phase_id, title, brief, instructions, expected_deliverables, submission_format, deliverable_hint, max_score, passing_score, allowed_evidence_types, allowed_mime_types, max_file_size_mb, is_required, rubric)
select v.id::uuid, sk.id, co.id, null::uuid, v.title, v.brief, v.instructions, v.expected_deliverables, v.submission_format, v.deliverable_hint, v.max_score, v.passing_score, v.allowed_evidence_types, v.allowed_mime_types, v.max_file_size_mb, v.is_required, v.rubric
from (
  values
    ('d0275d62-fe57-8036-7761-b44437ba981e', 'frontend-development', 'frontend-development-foundations', 'Final Practical Project: Build and Deploy a Responsive Business Website', 'Design, code, and deploy a multi-section responsive website for a real or fictional local business using semantic HTML5, responsive CSS (Flexbox & Grid), interactive DOM controls, and a validated contact/inquiry form.', 'Include at least 3 pages or 4 distinct sections (Hero, Services Grid, Interactive FAQ/Filter, Validated Inquiry Form), verify mobile responsiveness at 375px and desktop at 1440px, and publish to a live static host (GitHub Pages, Netlify, Cloudflare Pages, or Vercel).', '["Live deployed HTTPS website URL","Public Git repository link showing clean HTML/CSS/JS files","Screenshot or brief architecture & accessibility audit notes (focus order, contrast, and responsive breakpoints)"]'::jsonb, 'Live project URL + Git repository URL + optional screenshot/notes', 'Submit your deployed URL, Git repo URL, and explain how you tested responsiveness and form validation.', 25, 18, '["project_url","repo_url","screenshot","file","written"]'::jsonb, '["image/png","image/jpeg","image/webp","application/pdf","application/zip"]'::jsonb, 20, true, '[{"id":"r1","label":"Semantic HTML5 & Accessibility","description":"Valid landmarks, single h1, labelled form inputs, keyboard focus visibility.","maxPoints":7},{"id":"r2","label":"Responsive CSS Architecture","description":"Clean Flexbox/Grid layout across mobile (375px) and desktop (1440px) with zero horizontal overflow.","maxPoints":6},{"id":"r3","label":"JavaScript Interactivity & Validation","description":"Working DOM interactions (e.g. filter/FAQ) and friendly inline form validation without console errors.","maxPoints":6},{"id":"r4","label":"Live Deployment & Code Organisation","description":"Working HTTPS URL with relative asset paths and clean file structure.","maxPoints":6}]'::jsonb),
    ('1d619738-ed90-b833-09f7-280c491ce91d', 'graphic-design', 'graphic-design-foundations', 'Final Practical Project: Produce an Original Promotional Flyer for a Fictional Business', 'Design an original A5 or US Letter promotional flyer for a fictional local business or event, applying your brand sheet, 60-30-10 palette, paired typography, grid alignment, and clear call-to-action.', 'Include a clear headline, focal visual or illustration, offer/event details (date, venue, offer, CTA), and generous margins. Export as a crisp PNG/JPG preview or print-ready PDF and explain your typography, palette, and grid decisions.', '["Original promotional flyer file (PDF, PNG, JPG, or WebP)","Design rationale detailing target audience, font pairing, 60-30-10 colour values, and grid margins"]'::jsonb, 'Flyer upload (PDF/PNG/JPG/WebP) or public Figma/Canva share link + written rationale', 'Upload your promotional flyer (PDF/PNG/JPG, max 20 MB) or share a link, and explain your design choices.', 25, 18, '["file","screenshot","project_url","written"]'::jsonb, '["application/pdf","image/png","image/jpeg","image/webp"]'::jsonb, 20, true, '[{"id":"r1","label":"Visual Hierarchy & 3-Second Read","description":"Unmistakable focal headline, clear offer details, and prominent CTA.","maxPoints":7},{"id":"r2","label":"Typography & Grid Alignment","description":"Max 2 fonts, balanced scale contrast, clean alignment, and generous outer margins.","maxPoints":6},{"id":"r3","label":"Colour Contrast & Brand Fit","description":"Cohesive 60-30-10 palette with legible >= 4.5:1 text contrast.","maxPoints":6},{"id":"r4","label":"Production Polish & Rationale","description":"Clean export quality, zero clipped elements, and clear explanation of decisions.","maxPoints":6}]'::jsonb),
    ('c0835f0e-6a94-6eee-ab76-ecedb36338b4', 'digital-marketing-fundamentals', 'digital-marketing-foundations', 'Final Practical Project: Develop a Seven-Day Integrated Marketing Campaign', 'Plan and draft a complete 7-day marketing campaign for a real or fictional product/service, connecting audience research, daily channel deliverables, copywriting, UTM tracking, and optimisation KPIs.', 'Include: (1) Target audience ICP + core value proposition, (2) Day 1–7 channel calendar (Social, Email, and Paid/Landing touchpoints), (3) At least 2 complete copy deliverables (1 PAS email + 2 social posts), (4) Standardised UTM link plan, and (5) Primary KPIs + 1 Day-8 A/B test plan.', '["Complete 7-day campaign plan (submitted directly as structured text, PDF/DOCX/CSV upload, or public Notion/Docs link)","Target audience profile, copy deliverables, UTM schema, and success metrics"]'::jsonb, 'Written campaign blueprint, PDF/DOCX/CSV upload, or shared document link', 'Paste your 7-day campaign plan directly or upload a PDF/DOCX/CSV document with your UTM table and copy drafts.', 25, 18, '["written","file","project_url","screenshot"]'::jsonb, '["application/pdf","application/vnd.openxmlformats-officedocument.wordprocessingml.document","text/csv","text/plain","image/png","image/jpeg"]'::jsonb, 20, true, '[{"id":"r1","label":"Audience Alignment & Value Proposition","description":"Clear ICP triggers, objections, and coherent offer positioning.","maxPoints":6},{"id":"r2","label":"7-Day Sequencing & Copy Quality","description":"Logical multi-day arc with specific, outcome-driven copy and clear CTAs.","maxPoints":7},{"id":"r3","label":"UTM Hygiene & Measurement Plan","description":"Consistent UTM links and actionable funnel KPIs (CTR, CVR, CPA).","maxPoints":6},{"id":"r4","label":"Optimisation Readiness","description":"Concrete post-launch diagnostic thresholds and A/B test hypothesis.","maxPoints":6}]'::jsonb),
    ('1499f3ea-3553-be49-09f5-1dc9d659c4e0', 'public-speaking', 'communication-and-public-speaking', 'Final Practical Project: Record a Structured Two-Minute Presentation with Outline and Reflection', 'Prepare and record an original 2-minute presentation (~1:45–2:15) on a topic relevant to your career or community, and submit your recording alongside your speech outline and 3-pass self-reflection.', 'Deliver a clear 15-second hook, 3 structured main points, and a deliberate closing call-to-action. Upload an audio or video recording (or private/unlisted video URL) plus paste your keyword outline and written reflection covering strengths and next rehearsal goals.', '["2-minute audio or video recording (MP4, WebM, MP3, WAV, M4A, or hosted link)","Structured presentation outline (Hook, 3 Pillars, Closing CTA)","Written 3-pass reflection evaluating vocal pacing, non-verbal delivery, and audience clarity"]'::jsonb, 'Audio/Video upload (MP4/WebM/MP3/WAV, max 50 MB) or presentation link + written outline & reflection', 'Attach your 2-minute audio/video file (or unlisted video link) and include your outline & reflection in the text boxes below.', 25, 18, '["audio","video","project_url","file","written"]'::jsonb, '["video/mp4","video/webm","video/quicktime","audio/mpeg","audio/wav","audio/mp4","audio/webm","audio/ogg","application/pdf"]'::jsonb, 50, true, '[{"id":"r1","label":"Presentation Structure & Timing","description":"Crisp opening hook, 3 clear pillars, strong closing CTA, ~2 minutes total.","maxPoints":7},{"id":"r2","label":"Vocal Clarity, Pacing & Pauses","description":"Steady conversational speed, natural emphasis, minimal fillers, clean audio.","maxPoints":6},{"id":"r3","label":"Presence & Audience Framing","description":"Direct eye/camera engagement, grounded posture, and audience-relevant examples.","maxPoints":6},{"id":"r4","label":"Outline Quality & Honest Self-Reflection","description":"Clean keyword outline paired with concrete 3-pass observations.","maxPoints":6}]'::jsonb)
) as v(id, skill_slug, course_slug, title, brief, instructions, expected_deliverables, submission_format, deliverable_hint, max_score, passing_score, allowed_evidence_types, allowed_mime_types, max_file_size_mb, is_required, rubric)
join public.skills sk on sk.slug = v.skill_slug
left join public.courses co on co.slug = v.course_slug
on conflict (id) do update set
  skill_id = excluded.skill_id,
  course_id = excluded.course_id,
  title = excluded.title,
  brief = excluded.brief,
  instructions = excluded.instructions,
  expected_deliverables = excluded.expected_deliverables,
  submission_format = excluded.submission_format,
  deliverable_hint = excluded.deliverable_hint,
  max_score = excluded.max_score,
  passing_score = excluded.passing_score,
  allowed_evidence_types = excluded.allowed_evidence_types,
  allowed_mime_types = excluded.allowed_mime_types,
  max_file_size_mb = excluded.max_file_size_mb,
  is_required = excluded.is_required,
  rubric = excluded.rubric;

-- 13. Opportunities (5)
insert into public.opportunities (title, organization, opportunity_type, work_mode, location, summary, about_role, responsibilities, requirements, required_skills, required_skill_slugs, other_info, org_tips, is_sample, apply_url)
values
  ('Paid Social & Meta Ads Coordinator', 'Kestrel Consumer Studio', 'Junior Role', 'Hybrid', 'London, UK', 'Plan, build, and optimize Meta acquisition and retargeting campaigns while reporting weekly ROAS and creative fatigue diagnostics.', 'Kestrel Consumer Studio manages growth campaigns for sustainable retail brands. As Paid Social & Meta Ads Coordinator, you will structure Meta ad accounts, draft multi-hook ad creatives, interpret pixel/CAPI signals, and present crisp optimization readouts.', '["Structure Campaign, Ad Set, and Ad tiers aligned with funnel conversion objectives.","Monitor CTR, CPA, Frequency, and 7-day ROAS trends across active campaigns.","Coordinate monthly social content calendars alongside brand designers.","Draft weekly BLUF campaign performance memos for account leads."]'::jsonb, '["Verified or demonstrated fluency in Facebook and Instagram Advertising.","Hands-on planning experience in Social Media Management.","Clear written business communication for client reporting."]'::jsonb, '[{"slug":"facebook-and-instagram-advertising","neededLevel":"practising"},{"slug":"social-media-management","neededLevel":"practising"},{"slug":"business-writing","neededLevel":"practising"}]'::jsonb, '["facebook-and-instagram-advertising","social-media-management","business-writing"]'::jsonb, '{"compensation":"£29,000 – £33,000 / year","duration":"Full-time · Permanent","schedule":"3 days studio (London), 2 days remote","deadline":"Rolling cohort review"}'::jsonb, '{"aboutOrg":"Kestrel emphasizes transparent attribution, creative testing discipline, and clear client communication without vanity reporting.","howToApply":"Include a campaign blueprint or creative test plan alongside your CV and highlight any completed Kord ad analytics projects.","tips":["Explain how you separate cold prospecting from warm retargeting audiences.","Show how you diagnose high CPM vs. low landing-page conversion."]}'::jsonb, true, 'https://example.org/opportunities/kestrel-meta-ads'),
  ('Editorial & Creative Content Fellow', 'Harbourline Storytelling Lab', 'Fellowship', 'Remote', 'Remote (UK / EU)', 'Craft compelling short fiction, brand essays, and narrative scripts while leading peer critique workshops.', 'Harbourline Storytelling Lab publishes community-funded fiction anthologies and narrative audio documentaries. Fellows develop vivid scenes, sharpen dialogue subtext, and edit long-form manuscripts to publication standard.', '["Write and revise 1,500–2,500 word narrative pieces anchored in sensory scene work.","Develop voice-consistent character dialogue and structural outlines.","Collaborate with editorial leads during line-editing and copy-proofing passes."]'::jsonb, '["Practising or higher mastery in Creative Writing.","Strong command of narrative pacing, dialogue clarity, and structural editing."]'::jsonb, '[{"slug":"creative-writing","neededLevel":"practising"},{"slug":"effective-communication","neededLevel":"practising"}]'::jsonb, '["creative-writing","effective-communication"]'::jsonb, '{"compensation":"£2,050 / month fellowship stipend","duration":"6 months","schedule":"Remote · Async editorial sprints + Tuesday table reads","deadline":"Applications reviewed weekly"}'::jsonb, '{"aboutOrg":"Harbourline values original voice, disciplined revision habits, and generous peer critique.","howToApply":"Submit a 600–1,200 word original scene or story draft demonstrating scene grounding and earned dialogue.","tips":["Lead immediately with action and specific sensory detail rather than backstory exposition.","Highlight one concrete structural revision you made between draft 1 and draft 2."]}'::jsonb, true, 'https://example.org/opportunities/harbourline-editorial'),
  ('Venture Operations & Strategy Intern', 'Northbridge Impact Ventures', 'Internship', 'Hybrid', 'Manchester, UK', 'Support early-stage founders with customer discovery synthesis, unit-economics modeling, and investor update memos.', 'Northbridge Impact Ventures backs seed-stage civic and climate startups. As Venture Operations Intern, you will help founders map problem interviews, test MVP hypotheses, and communicate clear milestones.', '["Synthesize founder customer discovery notes into actionable opportunity memos.","Audit startup unit economics, break-even assumptions, and launch milestones.","Coordinate pitch rehearsal briefings with portfolio teams."]'::jsonb, '["Solid grounding in Entrepreneurship and lean validation workflows.","Confident Effective Communication and concise Business Writing."]'::jsonb, '[{"slug":"entrepreneurship","neededLevel":"practising"},{"slug":"effective-communication","neededLevel":"practising"},{"slug":"business-writing","neededLevel":"practising"}]'::jsonb, '["entrepreneurship","effective-communication","business-writing"]'::jsonb, '{"compensation":"£1,950 / month paid internship","duration":"12 weeks (extendable)","schedule":"2 days Manchester hub, 3 days remote","deadline":"Closes in 21 days"}'::jsonb, '{"aboutOrg":"Northbridge prefers evidence of real customer conversations over polished slide templates.","howToApply":"Attach a 1-page Venture Validation Canvas or startup brief alongside your tailored CV.","tips":["Name the riskiest assumption in any business model and how you would test it cheaply.","Quantify customer pain with specific frequency or cost estimates."]}'::jsonb, true, 'https://example.org/opportunities/northbridge-venture'),
  ('Junior Web & Visual Systems Developer', 'OpenCouncil Digital Studio', 'Apprenticeship', 'Remote', 'Remote', 'Build accessible, responsive web interfaces and visual communication assets for public-benefit web services.', 'OpenCouncil Digital Studio creates accessible web portals and community tools. You will build semantic HTML/CSS layouts, accessible interactive JavaScript modules, and crisp visual graphics.', '["Implement responsive grid layouts with WCAG AA contrast and keyboard focus order.","Build modular vanilla JavaScript components with clean DOM state handling.","Create campaign flyers, info cards, and UI assets using consistent typographic hierarchy."]'::jsonb, '["Practising or higher skill level in Web Development.","Working eye for visual hierarchy and layout in Graphic Design.","Clear documentation and collaborative communication."]'::jsonb, '[{"slug":"web-development","neededLevel":"practising"},{"slug":"graphic-design","neededLevel":"practising"},{"slug":"effective-communication","neededLevel":"declared"}]'::jsonb, '["web-development","graphic-design","effective-communication"]'::jsonb, '{"compensation":"£25,500 / year + hardware budget","duration":"12-month apprenticeship","schedule":"Full-time · Remote","deadline":"Next intake open"}'::jsonb, '{"aboutOrg":"OpenCouncil prioritizes native browser standards, semantic HTML, and crisp design restraint over bloated frameworks.","howToApply":"Share a link to a live semantic web page or accessible UI audit plus your tailored resume.","tips":["Test every interactive control using only Tab, Shift+Tab, and Enter before submitting.","Explain your font-scale and contrast choices briefly."]}'::jsonb, true, 'https://example.org/opportunities/opencouncil-web'),
  ('Social Media & Brand Content Associate', 'Civic Bloom Collective', 'Project', 'Remote', 'Remote', 'Design and schedule a 30-day multi-platform social campaign pairing cohesive graphics with measurable audience engagement.', 'Civic Bloom Collective runs educational initiatives for independent creators and local makers. In this 10-week project, you will plan content pillars, produce visual assets, and measure save/share retention.', '["Produce a 30-day multi-platform content calendar with clear pillar ratios.","Design clean social carousels and promotional flyers with accessible typography.","Track weekly audience retention, saves, and referral click-throughs."]'::jsonb, '["Proven capability in Social Media Management and Graphic Design.","Concise written hooks and community reply etiquette."]'::jsonb, '[{"slug":"social-media-management","neededLevel":"practising"},{"slug":"graphic-design","neededLevel":"practising"},{"slug":"cv-and-resume-writing","neededLevel":"declared"}]'::jsonb, '["social-media-management","graphic-design","cv-and-resume-writing"]'::jsonb, '{"compensation":"£3,400 fixed project contract","duration":"10 weeks · Flexible part-time","schedule":"Async remote with weekly editorial syncs","deadline":"Closes in 14 days"}'::jsonb, '{"aboutOrg":"Civic Bloom focuses on practical, save-worthy educational posts instead of clickbait.","howToApply":"Include your 30-day social calendar or sample carousel graphic alongside a crisp 1-page CV.","tips":["Highlight save-rate or share-rate growth over raw follower counts.","Show 1 clear visual before/after hierarchy example."]}'::jsonb, true, 'https://example.org/opportunities/civic-bloom-social')
on conflict (title, organization) do update set
